var DIAGRAMS={};
DIAGRAMS.nvmearch={title:'NVMe architecture, application to NAND',cap:'Amber is host software and memory, blue is the NVM subsystem (controller, namespaces, firmware), green is the media. PCIe carries doorbell writes down, controller DMA both ways, and interrupts up. The dashed line is where the specification stops.',svg:`<svg viewBox="0 0 760 460" role="img" aria-label="NVMe stack from application through host driver, PCIe, controller and namespaces to NAND"><title>NVMe stack from application through host driver, PCIe, controller and namespaces to NAND</title><rect class="grp" x="14" y="8" width="732" height="160" rx="8" /><text class="xs f" x="24" y="22" text-anchor="start">HOST (software, memory)</text><rect class="tl" x="30" y="32" width="160" height="42" rx="6" /><text class="s h" x="110" y="50" text-anchor="middle">Application</text><text class="xs d" x="110" y="65" text-anchor="middle">read(), io_uring</text><rect class="tl" x="206" y="32" width="160" height="42" rx="6" /><text class="s h" x="286" y="50" text-anchor="middle">Filesystem</text><text class="xs d" x="286" y="65" text-anchor="middle">ext4, XFS, raw device</text><rect class="tl" x="382" y="32" width="160" height="42" rx="6" /><text class="s h" x="462" y="50" text-anchor="middle">Block layer</text><text class="xs d" x="462" y="65" text-anchor="middle">blk-mq on Linux</text><rect class="tl" x="558" y="32" width="160" height="42" rx="6" /><text class="s h" x="638" y="50" text-anchor="middle">NVMe driver</text><text class="xs d" x="638" y="65" text-anchor="middle">queues, doorbells, IRQs</text><line class="lna" x1="190" y1="53" x2="198.0" y2="53.0"/><polygon class="ah" points="206.0,53.0 197.0,57.5 197.0,48.5"/><line class="lna" x1="366" y1="53" x2="374.0" y2="53.0"/><polygon class="ah" points="382.0,53.0 373.0,57.5 373.0,48.5"/><line class="lna" x1="542" y1="53" x2="550.0" y2="53.0"/><polygon class="ah" points="558.0,53.0 549.0,57.5 549.0,48.5"/><line class="lna" x1="638" y1="74" x2="638.0" y2="92.0"/><polygon class="ah" points="638.0,100.0 633.5,91.0 642.5,91.0"/><text class="xs d" x="646" y="92" text-anchor="start">builds 64 B SQEs</text><rect class="tl" x="382" y="100" width="336" height="58" rx="6" /><text class="s h" x="550" y="115" text-anchor="middle">Host memory</text><rect class="box" x="392" y="122" width="100" height="26" rx="3" /><text class="xs" x="442" y="139" text-anchor="middle">SQs: 64 B SQEs</text><rect class="box" x="498" y="122" width="100" height="26" rx="3" /><text class="xs" x="548" y="139" text-anchor="middle">CQs: 16 B CQEs</text><rect class="box" x="604" y="122" width="100" height="26" rx="3" /><text class="xs" x="654" y="139" text-anchor="middle">data buffers</text><text class="xs d" x="30" y="112" text-anchor="start">The driver owns the queue memory,</text><text class="xs d" x="30" y="126" text-anchor="start">the doorbell writes and the</text><text class="xs d" x="30" y="140" text-anchor="start">interrupt handlers. Everything</text><text class="xs d" x="30" y="154" text-anchor="start">above it is ordinary OS code.</text><rect class="box" x="30" y="192" width="154" height="40" rx="6" /><text class="s h" x="107" y="209" text-anchor="middle">MMIO writes</text><text class="xs d" x="107" y="223" text-anchor="middle">doorbells</text><rect class="box" x="198" y="192" width="154" height="40" rx="6" /><text class="s h" x="275" y="209" text-anchor="middle">DMA by controller</text><text class="xs d" x="275" y="223" text-anchor="middle">SQE, data, CQE</text><rect class="box" x="366" y="192" width="154" height="40" rx="6" /><text class="s h" x="443" y="209" text-anchor="middle">MSI-X writes</text><text class="xs d" x="443" y="223" text-anchor="middle">interrupts</text><rect class="grp" x="536" y="192" width="194" height="40" rx="6" /><text class="s h" x="633" y="209" text-anchor="middle">PCIe transport</text><text class="xs d" x="633" y="223" text-anchor="middle">Fabrics: RDMA, TCP or FC</text><line class="lna" x1="107" y1="168" x2="107.0" y2="184.0"/><polygon class="ah" points="107.0,192.0 102.5,183.0 111.5,183.0"/><line class="lnc" x1="266" y1="168" x2="266.0" y2="184.0"/><polygon class="ahc" points="266.0,192.0 261.5,183.0 270.5,183.0"/><line class="lnc" x1="288" y1="192" x2="288.0" y2="176.0"/><polygon class="ahc" points="288.0,168.0 292.5,177.0 283.5,177.0"/><line class="lnc" x1="443" y1="192" x2="443.0" y2="176.0"/><polygon class="ahc" points="443.0,168.0 447.5,177.0 438.5,177.0"/><line class="lna" x1="107" y1="232" x2="107.0" y2="254.0"/><polygon class="ah" points="107.0,262.0 102.5,253.0 111.5,253.0"/><line class="lnc" x1="266" y1="262" x2="266.0" y2="240.0"/><polygon class="ahc" points="266.0,232.0 270.5,241.0 261.5,241.0"/><line class="lnc" x1="288" y1="232" x2="288.0" y2="254.0"/><polygon class="ahc" points="288.0,262.0 283.5,253.0 292.5,253.0"/><line class="lnc" x1="443" y1="262" x2="443.0" y2="240.0"/><polygon class="ahc" points="443.0,232.0 447.5,241.0 438.5,241.0"/><rect class="grp" x="14" y="240" width="732" height="214" rx="8" /><text class="xs f" x="738" y="254" text-anchor="end">NVM SUBSYSTEM: the whole device as the host sees it</text><rect class="dl" x="30" y="262" width="490" height="88" rx="6" /><text class="s h" x="275" y="279" text-anchor="middle">Controller (a logical entity, BAR0 registers)</text><rect class="box" x="36" y="288" width="112" height="50" rx="4" /><text class="s h" x="92" y="309" text-anchor="middle">Registers</text><text class="xs d" x="92" y="325" text-anchor="middle">BAR0, doorbells</text><rect class="box" x="158" y="288" width="112" height="50" rx="4" /><text class="s h" x="214" y="309" text-anchor="middle">Admin QP</text><text class="xs d" x="214" y="325" text-anchor="middle">exactly one</text><rect class="box" x="280" y="288" width="112" height="50" rx="4" /><text class="s h" x="336" y="309" text-anchor="middle">I/O QPs</text><text class="xs d" x="336" y="325" text-anchor="middle">up to thousands</text><rect class="box" x="402" y="288" width="112" height="50" rx="4" /><text class="s h" x="458" y="309" text-anchor="middle">Engine</text><text class="xs d" x="458" y="325" text-anchor="middle">runs commands</text><rect class="dl" x="536" y="262" width="194" height="88" rx="6" /><text class="s h" x="633" y="279" text-anchor="middle">Namespaces</text><rect class="box" x="548" y="288" width="52" height="24" rx="3" /><text class="xs h" x="574" y="304" text-anchor="middle">NS 1</text><rect class="box" x="608" y="288" width="52" height="24" rx="3" /><text class="xs h" x="634" y="304" text-anchor="middle">NS 2</text><rect class="box" x="668" y="288" width="52" height="24" rx="3" /><text class="xs h" x="694" y="304" text-anchor="middle">NS n</text><text class="xs d" x="633" y="328" text-anchor="middle">LBA address spaces,</text><text class="xs d" x="633" y="341" text-anchor="middle">mapped to NAND by the FTL</text><line class="lnd" x1="30" y1="370" x2="730" y2="370"/><text class="xs f" x="730" y="365" text-anchor="end">NVMe stops above this line: the host-to-controller interface</text><rect class="dl" x="30" y="378" width="700" height="30" rx="6" /><text class="s" x="380" y="397" text-anchor="middle">Firmware: FTL, garbage collection, wear leveling, ECC (internal, not defined by NVMe)</text><rect class="pl" x="30" y="416" width="700" height="30" rx="6" /><text class="s h" x="380" y="435" text-anchor="middle">NAND flash media</text></svg>`};
DIAGRAMS.regmap={title:'BAR0 controller register map',cap:'Amber registers are the host controls, blue ones tell the host what the device is and what state it is in. CC is at 14h and CSTS at 1Ch, with 18h reserved between them. Doorbells start at 1000h and are spaced by the CAP.DSTRD stride.',svg:`<svg viewBox="0 0 760 458" role="img" aria-label="Register offsets in BAR0 from CAP at 00h to the doorbells at 1000h"><title>Register offsets in BAR0 from CAP at 00h to the doorbells at 1000h</title><text class="s h" x="20" y="16" text-anchor="start">BAR0 offsets, not to scale</text><text class="xs d" x="20" y="30" text-anchor="start">first 4 KB = registers, doorbells from 1000h</text><rect class="dl" x="76" y="38" width="294" height="32" rx="3" /><text class="s h" x="68" y="58.0" text-anchor="end">00h</text><text class="s h" x="86" y="58.0" text-anchor="start">CAP</text><text class="xs d" x="148" y="58.0" text-anchor="start">capabilities (read-only)</text><text class="xs d" x="362" y="58.0" text-anchor="end">8 B</text><rect class="dl" x="76" y="72" width="294" height="24" rx="3" /><text class="s h" x="68" y="88.0" text-anchor="end">08h</text><text class="s h" x="86" y="88.0" text-anchor="start">VS</text><text class="xs d" x="148" y="88.0" text-anchor="start">version (read-only)</text><text class="xs d" x="362" y="88.0" text-anchor="end">4 B</text><rect class="tl" x="76" y="98" width="294" height="24" rx="3" /><text class="s h" x="68" y="114.0" text-anchor="end">0Ch</text><text class="s h" x="86" y="114.0" text-anchor="start">INTMS</text><text class="xs d" x="148" y="114.0" text-anchor="start">mask set, pin/MSI</text><text class="xs d" x="362" y="114.0" text-anchor="end">4 B</text><rect class="tl" x="76" y="124" width="294" height="24" rx="3" /><text class="s h" x="68" y="140.0" text-anchor="end">10h</text><text class="s h" x="86" y="140.0" text-anchor="start">INTMC</text><text class="xs d" x="148" y="140.0" text-anchor="start">mask clear, pin/MSI</text><text class="xs d" x="362" y="140.0" text-anchor="end">4 B</text><rect class="tl" x="76" y="150" width="294" height="24" rx="3" /><text class="s h" x="68" y="166.0" text-anchor="end">14h</text><text class="s h" x="86" y="166.0" text-anchor="start">CC</text><text class="xs d" x="148" y="166.0" text-anchor="start">controller configuration</text><text class="xs d" x="362" y="166.0" text-anchor="end">4 B</text><rect class="grp" x="76" y="176" width="294" height="24" rx="3" /><text class="s h" x="68" y="192.0" text-anchor="end">18h</text><text class="xs d" x="86" y="192.0" text-anchor="start">reserved</text><text class="xs d" x="362" y="192.0" text-anchor="end"></text><rect class="dl" x="76" y="202" width="294" height="24" rx="3" /><text class="s h" x="68" y="218.0" text-anchor="end">1Ch</text><text class="s h" x="86" y="218.0" text-anchor="start">CSTS</text><text class="xs d" x="148" y="218.0" text-anchor="start">status: RDY, CFS, SHST</text><text class="xs d" x="362" y="218.0" text-anchor="end">4 B</text><rect class="tl" x="76" y="228" width="294" height="24" rx="3" /><text class="s h" x="68" y="244.0" text-anchor="end">20h</text><text class="s h" x="86" y="244.0" text-anchor="start">NSSR</text><text class="xs d" x="148" y="244.0" text-anchor="start">subsystem reset trigger</text><text class="xs d" x="362" y="244.0" text-anchor="end">4 B</text><rect class="tl" x="76" y="254" width="294" height="24" rx="3" /><text class="s h" x="68" y="270.0" text-anchor="end">24h</text><text class="s h" x="86" y="270.0" text-anchor="start">AQA</text><text class="xs d" x="148" y="270.0" text-anchor="start">admin queue sizes</text><text class="xs d" x="362" y="270.0" text-anchor="end">4 B</text><rect class="tl" x="76" y="280" width="294" height="32" rx="3" /><text class="s h" x="68" y="300.0" text-anchor="end">28h</text><text class="s h" x="86" y="300.0" text-anchor="start">ASQ</text><text class="xs d" x="148" y="300.0" text-anchor="start">admin SQ base address</text><text class="xs d" x="362" y="300.0" text-anchor="end">8 B</text><rect class="tl" x="76" y="314" width="294" height="32" rx="3" /><text class="s h" x="68" y="334.0" text-anchor="end">30h</text><text class="s h" x="86" y="334.0" text-anchor="start">ACQ</text><text class="xs d" x="148" y="334.0" text-anchor="start">admin CQ base address</text><text class="xs d" x="362" y="334.0" text-anchor="end">8 B</text><rect class="box" x="76" y="348" width="294" height="24" rx="3" /><text class="s h" x="68" y="364.0" text-anchor="end">38h</text><text class="s h" x="86" y="364.0" text-anchor="start">CMBLOC</text><text class="xs d" x="148" y="364.0" text-anchor="start">CMB location</text><text class="xs d" x="362" y="364.0" text-anchor="end">4 B</text><rect class="box" x="76" y="374" width="294" height="24" rx="3" /><text class="s h" x="68" y="390.0" text-anchor="end">3Ch</text><text class="s h" x="86" y="390.0" text-anchor="start">CMBSZ</text><text class="xs d" x="148" y="390.0" text-anchor="start">CMB size</text><text class="xs d" x="362" y="390.0" text-anchor="end">4 B</text><text class="xs f" x="223.0" y="412" text-anchor="middle">continues at 40h</text><text class="xs f" x="596.0" y="30" text-anchor="middle">continued</text><rect class="box" x="452" y="38" width="288" height="24" rx="3" /><text class="s h" x="444" y="54" text-anchor="end">40h</text><text class="s h" x="462" y="54.0" text-anchor="start">BPINFO</text><text class="xs d" x="524" y="54.0" text-anchor="start">boot partition info</text><text class="xs d" x="732" y="54.0" text-anchor="end">4 B</text><rect class="box" x="452" y="64" width="288" height="24" rx="3" /><text class="s h" x="444" y="80" text-anchor="end">44h</text><text class="s h" x="462" y="80.0" text-anchor="start">BPRSEL</text><text class="xs d" x="524" y="80.0" text-anchor="start">boot partition read select</text><text class="xs d" x="732" y="80.0" text-anchor="end">4 B</text><rect class="box" x="452" y="90" width="288" height="32" rx="3" /><text class="s h" x="444" y="106" text-anchor="end">48h</text><text class="s h" x="462" y="110.0" text-anchor="start">BPMBL</text><text class="xs d" x="524" y="110.0" text-anchor="start">BP memory buffer location</text><text class="xs d" x="732" y="110.0" text-anchor="end">8 B</text><rect class="box" x="452" y="124" width="288" height="52" rx="3" /><text class="s h" x="444" y="140" text-anchor="end">50h</text><text class="s h" x="596.0" y="144" text-anchor="middle">CMBMSC CMBSTS CMBEBS</text><text class="s h" x="596.0" y="158" text-anchor="middle">CMBSWTP NSSD CRTO</text><text class="xs d" x="596.0" y="171" text-anchor="middle">newer CMB controls, shutdown, timeouts</text><text class="xs d" x="444" y="172" text-anchor="end">to 68h</text><rect class="grp" x="452" y="178" width="288" height="22" rx="3" /><text class="xs d" x="596.0" y="193" text-anchor="middle">reserved gap: never write</text><rect class="box" x="452" y="202" width="288" height="52" rx="3" /><text class="s h" x="444" y="218" text-anchor="end">E00h</text><text class="s h" x="596.0" y="220" text-anchor="middle">PMR block: PMRCAP PMRCTL</text><text class="s h" x="596.0" y="234" text-anchor="middle">PMRSTS PMREBS PMRSWTP</text><text class="s h" x="596.0" y="248" text-anchor="middle">PMRMSCL PMRMSCU</text><text class="xs d" x="444" y="236" text-anchor="end">to E18h</text><rect class="grp" x="452" y="256" width="288" height="22" rx="3" /><text class="xs d" x="596.0" y="271" text-anchor="middle">reserved gap</text><rect class="tl" x="452" y="280" width="288" height="74" rx="3" /><text class="s h" x="444" y="296" text-anchor="end">1000h</text><text class="s h" x="596.0" y="298" text-anchor="middle">Doorbells, 4 B each, write-only</text><text class="xs" x="596.0" y="314" text-anchor="middle">SQ y tail = 1000h + (2y) x stride</text><text class="xs" x="596.0" y="328" text-anchor="middle">CQ y head = 1000h + (2y+1) x stride</text><text class="xs d" x="596.0" y="343" text-anchor="middle">stride = 4 &lt;&lt; CAP.DSTRD bytes</text><text class="xs d" x="452" y="370" text-anchor="start">64-bit registers: CAP, ASQ, ACQ, BPMBL, CMBMSC.</text><text class="xs d" x="452" y="384" text-anchor="start">All others are 32-bit. Gaps are reserved.</text><rect class="tl" x="20" y="434" width="14" height="12" rx="2" /><text class="xs d" x="40" y="444" text-anchor="start">host writes (controls, doorbells)</text><rect class="dl" x="280" y="434" width="14" height="12" rx="2" /><text class="xs d" x="300" y="444" text-anchor="start">device reports (read-only, status)</text><rect class="box" x="540" y="434" width="14" height="12" rx="2" /><text class="xs d" x="560" y="444" text-anchor="start">optional blocks: CMB, BP, PMR</text></svg>`};
DIAGRAMS.ctrlinit={title:'Controller enable and initialization',cap:'Amber steps are host register writes, blue is the controller answering through CSTS.RDY, green is normal operation over the admin queue. The red branch is the bounded wait: if RDY never rises within CAP.TO x 500 ms the controller is treated as failed.',svg:`<svg viewBox="0 0 760 444" role="img" aria-label="Flow chart from PCIe up, through quiesce, admin queue setup, CC configure and enable, to waiting for RDY and admin commands"><title>Flow chart from PCIe up, through quiesce, admin queue setup, CC configure and enable, to waiting for RDY and admin commands</title><rect class="tl" x="20" y="14" width="380" height="40" rx="6" /><text class="s ac" x="34" y="39" text-anchor="middle">0</text><text class="s h" x="218.0" y="32" text-anchor="middle">PCIe is up</text><text class="xs d" x="218.0" y="46" text-anchor="middle">memory space and bus master on, BAR0 mapped, admin MSI-X ready</text><rect class="tl" x="20" y="74" width="380" height="40" rx="6" /><text class="s ac" x="34" y="99" text-anchor="middle">1</text><text class="s h" x="218.0" y="92" text-anchor="middle">Quiesce</text><text class="xs d" x="218.0" y="106" text-anchor="middle">if CC.EN = 1, write CC.EN = 0. Wait until CSTS.RDY = 0</text><rect class="tl" x="20" y="134" width="380" height="40" rx="6" /><text class="s ac" x="34" y="159" text-anchor="middle">2</text><text class="s h" x="218.0" y="152" text-anchor="middle">Admin queues</text><text class="xs d" x="218.0" y="166" text-anchor="middle">write AQA, ASQ, ACQ (sizes and base addresses)</text><rect class="tl" x="20" y="194" width="380" height="40" rx="6" /><text class="s ac" x="34" y="219" text-anchor="middle">3</text><text class="s h" x="218.0" y="212" text-anchor="middle">Configure</text><text class="xs d" x="218.0" y="226" text-anchor="middle">write CC: MPS, CSS, AMS, IOSQES=6, IOCQES=4 (EN still 0)</text><rect class="tl" x="20" y="254" width="380" height="40" rx="6" /><text class="s ac" x="34" y="279" text-anchor="middle">4</text><text class="s h" x="218.0" y="272" text-anchor="middle">Enable</text><text class="xs d" x="218.0" y="286" text-anchor="middle">write CC.EN = 1</text><rect class="dl" x="20" y="314" width="380" height="40" rx="6" /><text class="s ac" x="34" y="339" text-anchor="middle">5</text><text class="s h" x="218.0" y="332" text-anchor="middle">Wait for ready</text><text class="xs d" x="218.0" y="346" text-anchor="middle">poll CSTS.RDY until it reads 1</text><line class="lna" x1="210.0" y1="54" x2="210.0" y2="66.0"/><polygon class="ah" points="210.0,74.0 205.5,65.0 214.5,65.0"/><line class="lna" x1="210.0" y1="114" x2="210.0" y2="126.0"/><polygon class="ah" points="210.0,134.0 205.5,125.0 214.5,125.0"/><line class="lna" x1="210.0" y1="174" x2="210.0" y2="186.0"/><polygon class="ah" points="210.0,194.0 205.5,185.0 214.5,185.0"/><line class="lna" x1="210.0" y1="234" x2="210.0" y2="246.0"/><polygon class="ah" points="210.0,254.0 205.5,245.0 214.5,245.0"/><line class="lna" x1="210.0" y1="294" x2="210.0" y2="306.0"/><polygon class="ah" points="210.0,314.0 205.5,305.0 214.5,305.0"/><line class="lng" x1="210.0" y1="354" x2="210.0" y2="366.0"/><polygon class="ah" points="210.0,374.0 205.5,365.0 214.5,365.0"/><text class="xs gr" x="220.0" y="368" text-anchor="start">RDY = 1</text><rect class="pl" x="20" y="374" width="380" height="58" rx="6" /><text class="s ac" x="34" y="407" text-anchor="middle">6</text><text class="s h" x="218.0" y="392" text-anchor="middle">Admin commands on queue 0</text><text class="xs d" x="218.0" y="406" text-anchor="middle">Identify Controller, Set Features (Number of Queues),</text><text class="xs d" x="218.0" y="420" text-anchor="middle">Create I/O CQ, Create I/O SQ, Identify namespaces, AERs</text><text class="s h" x="432" y="30" text-anchor="start">why this order</text><text class="xs d" x="432" y="92" text-anchor="start">A reset that is still running must</text><text class="xs d" x="432" y="106" text-anchor="start">finish before you write config.</text><text class="xs d" x="432" y="152" text-anchor="start">Write these before EN: the controller may</text><text class="xs d" x="432" y="166" text-anchor="start">fetch from them as soon as RDY = 1.</text><text class="xs d" x="432" y="212" text-anchor="start">Some drivers do this and step 4 in one</text><text class="xs d" x="432" y="226" text-anchor="start">CC write.</text><line class="lnr" x1="400" y1="334" x2="416.0" y2="334.0"/><polygon class="ahr" points="424.0,334.0 415.0,338.5 415.0,329.5"/><text class="xs rd" x="420" y="322" text-anchor="end">no</text><rect class="er" x="432" y="310" width="308" height="48" rx="6" /><text class="s h" x="586" y="329" text-anchor="middle">Timeout after CAP.TO x 500 ms</text><text class="xs d" x="586" y="345" text-anchor="middle">treat the controller as failed</text><text class="xs d" x="432" y="396" text-anchor="start">CQ before SQ: Create I/O SQ names the</text><text class="xs d" x="432" y="410" text-anchor="start">CQ it completes into, so the CQ must exist.</text></svg>`};
DIAGRAMS.sqcq={title:'Submission and completion rings',cap:'Amber is the host and blue is the controller. Each side owns one pointer per ring: the host produces SQ entries and consumes CQ entries, the controller does the opposite. Doorbells, the SQHD field and the phase tag carry the pointers across.',svg:`<svg viewBox="0 0 760 472" role="img" aria-label="Submission and completion queues as ring buffers with head and tail pointers and the phase tag"><title>Submission and completion queues as ring buffers with head and tail pointers and the phase tag</title><text class="s h" x="154" y="14" text-anchor="start">Submission queue (SQ): 64 B entries</text><text class="xs f" x="608" y="14" text-anchor="end">8 slots shown, slot 7 wraps to 0</text><rect class="box" x="154" y="48" width="55" height="46" rx="3" /><text class="xs f" x="181.5" y="60" text-anchor="middle">0</text><text class="s d" x="181.5" y="76" text-anchor="middle">free</text><rect class="box" x="211" y="48" width="55" height="46" rx="3" /><text class="xs f" x="238.5" y="60" text-anchor="middle">1</text><text class="s d" x="238.5" y="76" text-anchor="middle">free</text><rect class="tl" x="268" y="48" width="55" height="46" rx="3" /><text class="xs f" x="295.5" y="60" text-anchor="middle">2</text><text class="s h" x="295.5" y="76" text-anchor="middle">SQE</text><text class="xs d" x="295.5" y="89" text-anchor="middle">posted</text><rect class="tl" x="325" y="48" width="55" height="46" rx="3" /><text class="xs f" x="352.5" y="60" text-anchor="middle">3</text><text class="s h" x="352.5" y="76" text-anchor="middle">SQE</text><text class="xs d" x="352.5" y="89" text-anchor="middle">posted</text><rect class="tl" x="382" y="48" width="55" height="46" rx="3" /><text class="xs f" x="409.5" y="60" text-anchor="middle">4</text><text class="s h" x="409.5" y="76" text-anchor="middle">SQE</text><text class="xs d" x="409.5" y="89" text-anchor="middle">posted</text><rect class="box" x="439" y="48" width="55" height="46" rx="3" /><text class="xs f" x="466.5" y="60" text-anchor="middle">5</text><text class="s d" x="466.5" y="76" text-anchor="middle">free</text><rect class="box" x="496" y="48" width="55" height="46" rx="3" /><text class="xs f" x="523.5" y="60" text-anchor="middle">6</text><text class="s d" x="523.5" y="76" text-anchor="middle">free</text><rect class="box" x="553" y="48" width="55" height="46" rx="3" /><text class="xs f" x="580.5" y="60" text-anchor="middle">7</text><text class="s d" x="580.5" y="76" text-anchor="middle">free</text><polygon class="ah" points="466.5,46 460.5,37 472.5,37"/><text class="xs ac" x="480.5" y="32" text-anchor="end">TAIL: host writes here, then rings SQ tail doorbell</text><polygon class="ahc" points="295.5,96 289.5,105 301.5,105"/><text class="xs cy" x="281.5" y="114" text-anchor="start">HEAD: controller fetches here, reports it in CQE SQHD</text><line class="lna" x1="104" y1="71" x2="142.0" y2="71.0"/><polygon class="ah" points="150.0,71.0 141.0,75.5 141.0,66.5"/><line class="lnc" x1="612" y1="71" x2="642.0" y2="71.0"/><polygon class="ahc" points="650.0,71.0 641.0,75.5 641.0,66.5"/><rect class="tl" x="14" y="44" width="90" height="54" rx="6" /><text class="s h" x="59" y="68" text-anchor="middle">Host</text><text class="xs d" x="59" y="84" text-anchor="middle">produces SQEs</text><rect class="dl" x="656" y="44" width="90" height="54" rx="6" /><text class="s h" x="701" y="68" text-anchor="middle">Controller</text><text class="xs d" x="701" y="84" text-anchor="middle">consumes SQEs</text><text class="s h" x="154" y="152" text-anchor="start">Completion queue (CQ): 16 B entries</text><text class="xs f" x="608" y="152" text-anchor="end">8 slots shown, slot 7 wraps to 0</text><rect class="box" x="154" y="186" width="55" height="46" rx="3" /><text class="xs f" x="181.5" y="198" text-anchor="middle">0</text><text class="s h" x="181.5" y="214" text-anchor="middle">CQE</text><text class="xs d" x="181.5" y="227" text-anchor="middle">P=1 seen</text><rect class="dl" x="211" y="186" width="55" height="46" rx="3" /><text class="xs f" x="238.5" y="198" text-anchor="middle">1</text><text class="s h" x="238.5" y="214" text-anchor="middle">CQE</text><text class="xs d" x="238.5" y="227" text-anchor="middle">P=1 new</text><rect class="dl" x="268" y="186" width="55" height="46" rx="3" /><text class="xs f" x="295.5" y="198" text-anchor="middle">2</text><text class="s h" x="295.5" y="214" text-anchor="middle">CQE</text><text class="xs d" x="295.5" y="227" text-anchor="middle">P=1 new</text><rect class="dl" x="325" y="186" width="55" height="46" rx="3" /><text class="xs f" x="352.5" y="198" text-anchor="middle">3</text><text class="s h" x="352.5" y="214" text-anchor="middle">CQE</text><text class="xs d" x="352.5" y="227" text-anchor="middle">P=1 new</text><rect class="box" x="382" y="186" width="55" height="46" rx="3" /><text class="xs f" x="409.5" y="198" text-anchor="middle">4</text><text class="s d" x="409.5" y="214" text-anchor="middle">empty</text><text class="xs d" x="409.5" y="227" text-anchor="middle">P=0</text><rect class="box" x="439" y="186" width="55" height="46" rx="3" /><text class="xs f" x="466.5" y="198" text-anchor="middle">5</text><text class="s d" x="466.5" y="214" text-anchor="middle">empty</text><text class="xs d" x="466.5" y="227" text-anchor="middle">P=0</text><rect class="box" x="496" y="186" width="55" height="46" rx="3" /><text class="xs f" x="523.5" y="198" text-anchor="middle">6</text><text class="s d" x="523.5" y="214" text-anchor="middle">empty</text><text class="xs d" x="523.5" y="227" text-anchor="middle">P=0</text><rect class="box" x="553" y="186" width="55" height="46" rx="3" /><text class="xs f" x="580.5" y="198" text-anchor="middle">7</text><text class="s d" x="580.5" y="214" text-anchor="middle">empty</text><text class="xs d" x="580.5" y="227" text-anchor="middle">P=0</text><polygon class="ahc" points="409.5,184 403.5,175 415.5,175"/><text class="xs cy" x="423.5" y="170" text-anchor="end">TAIL: controller writes here, phase tag marks it new</text><polygon class="ah" points="238.5,234 232.5,243 244.5,243"/><text class="xs ac" x="224.5" y="252" text-anchor="start">HEAD: host reads here, then rings CQ head doorbell</text><line class="lna" x1="150" y1="209" x2="112.0" y2="209.0"/><polygon class="ah" points="104.0,209.0 113.0,204.5 113.0,213.5"/><line class="lnc" x1="650" y1="209" x2="620.0" y2="209.0"/><polygon class="ahc" points="612.0,209.0 621.0,204.5 621.0,213.5"/><rect class="tl" x="14" y="182" width="90" height="54" rx="6" /><text class="s h" x="59" y="206" text-anchor="middle">Host</text><text class="xs d" x="59" y="222" text-anchor="middle">consumes CQEs</text><rect class="dl" x="656" y="182" width="90" height="54" rx="6" /><text class="s h" x="701" y="206" text-anchor="middle">Controller</text><text class="xs d" x="701" y="222" text-anchor="middle">produces CQEs</text><line class="ln" x1="20" y1="292" x2="740" y2="292"/><text class="xs f" x="20" y="312" text-anchor="start">pointer</text><text class="xs f" x="130" y="312" text-anchor="start">written by</text><text class="xs f" x="250" y="312" text-anchor="start">how the other side learns it</text><text class="s h" x="20" y="332" text-anchor="start">SQ tail</text><text class="s ac" x="130" y="332" text-anchor="start">host</text><text class="s" x="250" y="332" text-anchor="start">SQ tail doorbell write (MMIO)</text><text class="s h" x="20" y="352" text-anchor="start">SQ head</text><text class="s cy" x="130" y="352" text-anchor="start">controller</text><text class="s" x="250" y="352" text-anchor="start">SQ Head Pointer (SQHD) field in every CQE</text><text class="s h" x="20" y="372" text-anchor="start">CQ tail</text><text class="s cy" x="130" y="372" text-anchor="start">controller</text><text class="s" x="250" y="372" text-anchor="start">phase tag in the new CQE, plus an interrupt if enabled</text><text class="s h" x="20" y="392" text-anchor="start">CQ head</text><text class="s ac" x="130" y="392" text-anchor="start">host</text><text class="s" x="250" y="392" text-anchor="start">CQ head doorbell write (MMIO)</text><text class="xs d" x="20" y="424" text-anchor="start">Phase tag: the host zeroes the CQ first and expects P=1 on the first pass. The controller writes P=1,</text><text class="xs d" x="20" y="440" text-anchor="start">then inverts it each time its tail wraps. The host treats a slot as new only when its P equals the</text><text class="xs d" x="20" y="456" text-anchor="start">expected phase, so slot 4 (P=0) is not new yet. Neither side reads the other side pointer register.</text></svg>`};
DIAGRAMS.sqecqe={title:'SQE and CQE dword layout',cap:'The 64-byte SQE is built by the host, the 16-byte CQE by the controller. The command identifier in SQE DW0 comes back in CQE DW3, and DW3 bit 16 is the phase tag the host polls.',svg:`<svg viewBox="0 0 760 472" role="img" aria-label="Dword layout of the 64-byte submission queue entry and the 16-byte completion queue entry"><title>Dword layout of the 64-byte submission queue entry and the 16-byte completion queue entry</title><text class="s h" x="20" y="14" text-anchor="start">SQE: 64 bytes = 16 dwords (host writes it into the SQ)</text><text class="s h" x="84" y="46" text-anchor="end">DW0</text><rect class="pl" x="96" y="22" width="320" height="40" rx="2" /><text class="s h" x="256.0" y="41" text-anchor="middle">CID</text><text class="xs d" x="256.0" y="55" text-anchor="middle">31:16</text><rect class="tl" x="416" y="22" width="40" height="40" rx="2" /><text class="s h" x="436.0" y="41" text-anchor="middle">PSDT</text><text class="xs d" x="436.0" y="55" text-anchor="middle">15:14</text><rect class="box" x="456" y="22" width="80" height="40" rx="2" /><text class="s h" x="496.0" y="41" text-anchor="middle">Rsvd</text><text class="xs d" x="496.0" y="55" text-anchor="middle">13:10</text><rect class="tl" x="536" y="22" width="40" height="40" rx="2" /><text class="s h" x="556.0" y="41" text-anchor="middle">FUSE</text><text class="xs d" x="556.0" y="55" text-anchor="middle">9:8</text><rect class="tl" x="576" y="22" width="160" height="40" rx="2" /><text class="s h" x="656.0" y="41" text-anchor="middle">Opcode</text><text class="xs d" x="656.0" y="55" text-anchor="middle">7:0</text><text class="s h" x="84" y="90" text-anchor="end">DW1</text><rect class="tl" x="96" y="66" width="640" height="40" rx="2" /><text class="s h" x="416.0" y="85" text-anchor="middle">NSID</text><text class="xs d" x="416.0" y="99" text-anchor="middle">31:0</text><rect class="box" x="96" y="110" width="640" height="22" rx="2" /><text class="s h" x="84" y="125.0" text-anchor="end">DW2-3</text><text class="s h" x="416.0" y="125.0" text-anchor="middle">Reserved by the base layout (some commands use them)</text><rect class="tl" x="96" y="136" width="640" height="22" rx="2" /><text class="s h" x="84" y="151.0" text-anchor="end">DW4-5</text><text class="s h" x="416.0" y="151.0" text-anchor="middle">MPTR: metadata pointer (8 B)</text><rect class="tl" x="96" y="162" width="640" height="38" rx="2" /><text class="s h" x="84" y="185.0" text-anchor="end">DW6-9</text><text class="s h" x="416.0" y="179.0" text-anchor="middle">DPTR: PRP1 + PRP2, or one 16 B SGL descriptor</text><text class="xs d" x="416.0" y="192.0" text-anchor="middle">PSDT in DW0 selects which</text><rect class="tl" x="96" y="204" width="640" height="38" rx="2" /><text class="s h" x="84" y="227.0" text-anchor="end">DW10-15</text><text class="s h" x="416.0" y="221.0" text-anchor="middle">CDW10 to CDW15: command specific</text><text class="xs d" x="416.0" y="234.0" text-anchor="middle">6 dwords, meaning depends on the opcode</text><text class="s h" x="20" y="264" text-anchor="start">CQE: 16 bytes = 4 dwords (controller writes it into the CQ)</text><rect class="dl" x="96" y="272" width="640" height="22" rx="2" /><text class="s h" x="84" y="287.0" text-anchor="end">DW0</text><text class="s h" x="416.0" y="287.0" text-anchor="middle">Command-specific result (e.g. granted queue counts)</text><rect class="box" x="96" y="298" width="640" height="22" rx="2" /><text class="s h" x="84" y="313.0" text-anchor="end">DW1</text><text class="s h" x="416.0" y="313.0" text-anchor="middle">Reserved (some commands return a 64-bit result across DW0-1)</text><text class="s h" x="84" y="348" text-anchor="end">DW2</text><rect class="dl" x="96" y="324" width="320" height="40" rx="2" /><text class="s h" x="256.0" y="343" text-anchor="middle">SQ Identifier</text><text class="xs d" x="256.0" y="357" text-anchor="middle">31:16</text><rect class="dl" x="416" y="324" width="320" height="40" rx="2" /><text class="s h" x="576.0" y="343" text-anchor="middle">SQ Head Pointer</text><text class="xs d" x="576.0" y="357" text-anchor="middle">15:0</text><text class="s h" x="84" y="392" text-anchor="end">DW3</text><rect class="dl" x="96" y="368" width="20" height="40" rx="2" /><text class="xs h" x="106.0" y="392" text-anchor="middle">DNR</text><rect class="dl" x="116" y="368" width="20" height="40" rx="2" /><text class="xs h" x="126.0" y="392" text-anchor="middle">M</text><rect class="dl" x="136" y="368" width="40" height="40" rx="2" /><text class="s h" x="156.0" y="387" text-anchor="middle">CRD</text><text class="xs d" x="156.0" y="401" text-anchor="middle">29:28</text><rect class="dl" x="176" y="368" width="60" height="40" rx="2" /><text class="s h" x="206.0" y="387" text-anchor="middle">SCT</text><text class="xs d" x="206.0" y="401" text-anchor="middle">27:25</text><rect class="dl" x="236" y="368" width="160" height="40" rx="2" /><text class="s h" x="316.0" y="387" text-anchor="middle">SC</text><text class="xs d" x="316.0" y="401" text-anchor="middle">24:17</text><rect class="dl" x="396" y="368" width="20" height="40" rx="2" /><text class="xs h" x="406.0" y="392" text-anchor="middle">P</text><rect class="pl" x="416" y="368" width="320" height="40" rx="2" /><text class="s h" x="576.0" y="387" text-anchor="middle">CID</text><text class="xs d" x="576.0" y="401" text-anchor="middle">15:0</text><text class="xs d" x="20" y="430" text-anchor="start">Status field = DW3 bits 31:17 (SC, SCT, CRD, M, DNR: 15 bits). P is the phase tag, bit 16, just below it.</text><text class="xs d" x="20" y="446" text-anchor="start">SQID + CID identify the command. PSDT 00b: DPTR holds PRPs. 01b or 10b: SGL.</text><text class="xs d" x="20" y="462" text-anchor="start">Amber = host-written, blue = controller-written, green CID = echoed from SQE to CQE.</text></svg>`};
DIAGRAMS.prp={title:'PRP1, PRP2 and list chaining',cap:'The cases by page count, then the 3-or-more case in detail at 4 KiB pages: PRP2 points to a list page of 512 8-byte slots, and when more entries follow, the last slot is a link (blue arrow) to the next list page and the displaced data entry moves to its slot 0.',svg:`<svg viewBox="0 0 760 456" role="img" aria-label="PRP1 and PRP2 pointing to data pages and to chained PRP list pages"><title>PRP1 and PRP2 pointing to data pages and to chained PRP list pages</title><rect class="box" x="10" y="6" width="236" height="44" rx="6" /><text class="s h" x="128" y="24" text-anchor="middle">1 page</text><text class="xs" x="128" y="40" text-anchor="middle">PRP1 = data, PRP2 unused</text><rect class="box" x="262" y="6" width="236" height="44" rx="6" /><text class="s h" x="380" y="24" text-anchor="middle">2 pages</text><text class="xs" x="380" y="40" text-anchor="middle">PRP1 = data, PRP2 = 2nd page</text><rect class="tl" x="514" y="6" width="236" height="44" rx="6" /><text class="s h" x="632" y="24" text-anchor="middle">3 or more pages (drawn below)</text><text class="xs" x="632" y="40" text-anchor="middle">PRP1 = data, PRP2 = list pointer</text><rect class="grp" x="4" y="62" width="122" height="100" rx="6" /><rect class="tl" x="10" y="68" width="110" height="40" rx="6" /><text class="s h" x="65" y="86" text-anchor="middle">PRP1</text><text class="xs d" x="65" y="100" text-anchor="middle">8 B, offset ok</text><rect class="tl" x="10" y="116" width="110" height="40" rx="6" /><text class="s h" x="65" y="134" text-anchor="middle">PRP2</text><text class="xs d" x="65" y="148" text-anchor="middle">8 B, list ptr</text><text class="xs d" x="65" y="178" text-anchor="middle">DPTR (16 B in SQE)</text><line class="lna" x1="120" y1="88" x2="552.0" y2="88.0"/><polygon class="ah" points="560.0,88.0 551.0,92.5 551.0,83.5"/><text class="xs d" x="340" y="80" text-anchor="middle">first page, may start at an offset</text><rect class="dl" x="560" y="72" width="190" height="32" rx="6" /><text class="s h" x="655" y="92" text-anchor="middle">data page 1</text><rect class="tl" x="200" y="118" width="200" height="142" rx="6" /><text class="s h" x="300" y="134" text-anchor="middle">PRP list page A (4 KiB)</text><line class="lna" x1="120" y1="136" x2="192.0" y2="136.0"/><polygon class="ah" points="200.0,136.0 191.0,140.5 191.0,131.5"/><rect class="box" x="206" y="142" width="188" height="20" rx="2" /><text class="s" x="300" y="156" text-anchor="middle">slot 0</text><line class="lna" x1="394" y1="152" x2="552.0" y2="152.0"/><polygon class="ah" points="560.0,152.0 551.0,156.5 551.0,147.5"/><rect class="dl" x="560" y="142" width="190" height="20" rx="2" /><text class="s" x="655" y="156" text-anchor="middle">data page 2</text><rect class="box" x="206" y="164" width="188" height="20" rx="2" /><text class="s" x="300" y="178" text-anchor="middle">slot 1</text><line class="lna" x1="394" y1="174" x2="552.0" y2="174.0"/><polygon class="ah" points="560.0,174.0 551.0,178.5 551.0,169.5"/><rect class="dl" x="560" y="164" width="190" height="20" rx="2" /><text class="s" x="655" y="178" text-anchor="middle">data page 3</text><text class="s d" x="300" y="200" text-anchor="middle">...</text><rect class="box" x="206" y="208" width="188" height="20" rx="2" /><text class="s" x="300" y="222" text-anchor="middle">slot 510</text><line class="lna" x1="394" y1="218" x2="552.0" y2="218.0"/><polygon class="ah" points="560.0,218.0 551.0,222.5 551.0,213.5"/><rect class="dl" x="560" y="208" width="190" height="20" rx="2" /><text class="s" x="655" y="222" text-anchor="middle">data page 512</text><rect class="tl" x="206" y="230" width="188" height="20" rx="2" /><text class="s" x="300" y="244" text-anchor="middle">slot 511: link</text><text class="s d" x="655" y="200" text-anchor="middle">...</text><text class="xs d" x="10" y="208" text-anchor="start">Slots 0 to 510: one data</text><text class="xs d" x="10" y="222" text-anchor="start">entry per page, offset 0.</text><rect class="tl" x="200" y="290" width="200" height="118" rx="6" /><text class="s h" x="300" y="306" text-anchor="middle">PRP list page B</text><rect class="box" x="206" y="314" width="188" height="20" rx="2" /><text class="s" x="300" y="328" text-anchor="middle">slot 0</text><line class="lna" x1="394" y1="324" x2="552.0" y2="324.0"/><polygon class="ah" points="560.0,324.0 551.0,328.5 551.0,319.5"/><rect class="dl" x="560" y="314" width="190" height="20" rx="2" /><text class="s" x="655" y="328" text-anchor="middle">data page 513</text><rect class="box" x="206" y="336" width="188" height="20" rx="2" /><text class="s" x="300" y="350" text-anchor="middle">slot 1</text><line class="lna" x1="394" y1="346" x2="552.0" y2="346.0"/><polygon class="ah" points="560.0,346.0 551.0,350.5 551.0,341.5"/><rect class="dl" x="560" y="336" width="190" height="20" rx="2" /><text class="s" x="655" y="350" text-anchor="middle">data page 514</text><text class="s d" x="300" y="372" text-anchor="middle">...</text><rect class="box" x="206" y="380" width="188" height="20" rx="2" /><text class="s" x="300" y="394" text-anchor="middle">last slot: data</text><line class="lna" x1="394" y1="390" x2="552.0" y2="390.0"/><polygon class="ah" points="560.0,390.0 551.0,394.5 551.0,385.5"/><rect class="dl" x="560" y="380" width="190" height="20" rx="2" /><text class="s" x="655" y="394" text-anchor="middle">last data page</text><text class="s d" x="655" y="372" text-anchor="middle">...</text><polyline class="lnc" points="394,240 470,240 470,298 408.0,298.0"/><polygon class="ahc" points="400.0,298.0 409.0,293.5 409.0,302.5"/><text class="xs ac" x="478" y="274" text-anchor="start">link to the next list page</text><text class="xs d" x="10" y="326" text-anchor="start">Slot 0 holds the data entry</text><text class="xs d" x="10" y="340" text-anchor="start">that slot 511 of page A</text><text class="xs d" x="10" y="354" text-anchor="start">would have held.</text><text class="xs d" x="10" y="384" text-anchor="start">Final list page: all slots</text><text class="xs d" x="10" y="398" text-anchor="start">may hold data, no link.</text><text class="xs d" x="380" y="430" text-anchor="middle">Only PRP1 may have an offset. PRP2 used as a data pointer and every list entry are page aligned.</text><text class="xs d" x="380" y="445" text-anchor="middle">The controller decides page or list from the transfer size, never from the value in PRP2.</text></svg>`};
DIAGRAMS.fwslots={title:'Firmware download, commit and activation',cap:'Download stages the image, Commit picks the slot (FS) and the action (CA), and only CA 1 and 2 wait for a reset while CA 3 activates live. Verify by reading the Firmware Slot log page and Identify Controller FR.',svg:`<svg viewBox="0 0 760 450" role="img" aria-label="Firmware update flow: download to image buffer, commit to a slot, activation by CA value, verify"><title>Firmware update flow: download to image buffer, commit to a slot, activation by CA value, verify</title><text class="s h ac" x="135" y="14" text-anchor="middle">Host commands</text><text class="s h cy" x="405" y="14" text-anchor="middle">Controller</text><text class="s h gr" x="653" y="14" text-anchor="middle">Result</text><rect class="tl" x="10" y="24" width="250" height="76" rx="6" /><text class="s h" x="135.0" y="41" text-anchor="middle">1 Discover: Identify Controller</text><text class="xs" x="135.0" y="56" text-anchor="middle">FRMW (byte 260): bits 3:1 slot count,</text><text class="xs" x="135.0" y="69" text-anchor="middle">bit 0 slot 1 read-only, bit 4 no-reset</text><text class="xs" x="135.0" y="82" text-anchor="middle">activation. Also FWUG, MTFA, MDTS.</text><rect class="tl" x="10" y="116" width="250" height="84" rx="6" /><text class="s h" x="135.0" y="133" text-anchor="middle">2 Firmware Image Download (11h)</text><text class="xs" x="135.0" y="148" text-anchor="middle">NUMD (0s based dwords) + dword offset</text><text class="xs" x="135.0" y="161" text-anchor="middle">chunk &lt;= MDTS, offset multiple of FWUG</text><text class="xs" x="135.0" y="174" text-anchor="middle">e.g. 4 MiB / 64 KiB = 64 commands,</text><text class="xs" x="135.0" y="187" text-anchor="middle">NUMD = 0x3FFF, offsets step 0x4000</text><rect class="tl" x="10" y="220" width="250" height="82" rx="6" /><text class="s h" x="135.0" y="237" text-anchor="middle">3 Firmware Commit (10h)</text><text class="xs" x="135.0" y="252" text-anchor="middle">CDW10 = (CA &lt;&lt; 3) | FS</text><text class="xs" x="135.0" y="265" text-anchor="middle">FS bits 2:0 = slot, CA bits 5:3 = action</text><text class="xs" x="135.0" y="278" text-anchor="middle">example: slot 2, CA 1 gives 0x0A</text><text class="xs" x="135.0" y="291" text-anchor="middle">FS = 0 lets the controller pick</text><line class="lna" x1="130" y1="100" x2="130.0" y2="108.0"/><polygon class="ah" points="130.0,116.0 125.5,107.0 134.5,107.0"/><line class="lna" x1="130" y1="200" x2="130.0" y2="212.0"/><polygon class="ah" points="130.0,220.0 125.5,211.0 134.5,211.0"/><rect class="tl" x="10" y="318" width="250" height="100" rx="6" /><text class="s h" x="135.0" y="335" text-anchor="middle">5 Verify after the reset</text><text class="xs" x="135.0" y="350" text-anchor="middle">Firmware Slot log page (03h):</text><text class="xs" x="135.0" y="363" text-anchor="middle">AFI bits 2:0 = active slot,</text><text class="xs" x="135.0" y="376" text-anchor="middle">bits 6:4 = slot for next reset,</text><text class="xs" x="135.0" y="389" text-anchor="middle">then FRS1 to FRS7 (8-byte revs).</text><text class="xs" x="135.0" y="402" text-anchor="middle">Identify Controller FR (bytes 71:64)</text><text class="xs" x="135.0" y="415" text-anchor="middle">shows the running revision.</text><line class="lna" x1="130" y1="302" x2="130.0" y2="310.0"/><polygon class="ah" points="130.0,318.0 125.5,309.0 134.5,309.0"/><rect class="dl" x="300" y="116" width="210" height="60" rx="6" /><text class="s h" x="405.0" y="133" text-anchor="middle">Image buffer</text><text class="xs" x="405.0" y="148" text-anchor="middle">downloaded image, staged,</text><text class="xs" x="405.0" y="161" text-anchor="middle">not in any slot yet</text><line class="lna" x1="260" y1="146" x2="292.0" y2="146.0"/><polygon class="ah" points="300.0,146.0 291.0,150.5 291.0,141.5"/><rect class="dl" x="300" y="220" width="210" height="188" rx="6" /><text class="s h" x="405" y="238" text-anchor="middle">Firmware slots</text><text class="xs d" x="405" y="252" text-anchor="middle">count = FRMW bits 3:1</text><rect class="box" x="306" y="262" width="198" height="22" rx="2" /><text class="xs" x="405" y="277" text-anchor="middle">slot 1 (read-only if FRMW bit 0)</text><rect class="tl" x="306" y="288" width="198" height="22" rx="2" /><text class="xs" x="405" y="303" text-anchor="middle">slot 2 (FS = 2 in the example)</text><rect class="box" x="306" y="314" width="198" height="22" rx="2" /><text class="xs" x="405" y="329" text-anchor="middle">slot 3</text><text class="xs d" x="405" y="351" text-anchor="middle">... up to 7 slots</text><text class="xs d" x="405" y="377" text-anchor="middle">CA 6 and 7 target a Boot</text><text class="xs d" x="405" y="390" text-anchor="middle">Partition (module 12).</text><line class="lna" x1="405" y1="176" x2="405.0" y2="212.0"/><polygon class="ah" points="405.0,220.0 400.5,211.0 409.5,211.0"/><text class="xs ac" x="413" y="202" text-anchor="start">CA 0, 1, 3: store new image</text><line class="lna" x1="260" y1="261" x2="292.0" y2="261.0"/><polygon class="ah" points="300.0,261.0 291.0,265.5 291.0,256.5"/><text class="xs ac" x="280" y="253" text-anchor="middle">FS</text><rect class="box" x="556" y="116" width="194" height="64" rx="6" /><text class="s h" x="653.0" y="133" text-anchor="middle">Rollback</text><text class="xs" x="653.0" y="148" text-anchor="middle">keep the old image in</text><text class="xs" x="653.0" y="161" text-anchor="middle">another slot, then commit</text><text class="xs" x="653.0" y="174" text-anchor="middle">it again with CA 2</text><text class="s h" x="653" y="212" text-anchor="middle">4 Activate, chosen by CA</text><rect class="box" x="556" y="220" width="194" height="40" rx="6" /><text class="s h" x="653.0" y="237" text-anchor="middle">CA 0: store only</text><text class="xs" x="653.0" y="252" text-anchor="middle">slot FS is not activated</text><rect class="tl" x="556" y="270" width="194" height="64" rx="6" /><text class="s h" x="653.0" y="287" text-anchor="middle">CA 1 and CA 2</text><text class="xs" x="653.0" y="302" text-anchor="middle">CA 1: store, then activate</text><text class="xs" x="653.0" y="315" text-anchor="middle">CA 2: activate slot FS as is</text><text class="xs" x="653.0" y="328" text-anchor="middle">both at the next reset</text><rect class="pl" x="556" y="344" width="194" height="64" rx="6" /><text class="s h" x="653.0" y="361" text-anchor="middle">CA 3: live activation</text><text class="xs" x="653.0" y="376" text-anchor="middle">activate now, no reset</text><text class="xs" x="653.0" y="389" text-anchor="middle">needs FRMW bit 4 = 1</text><text class="xs" x="653.0" y="402" text-anchor="middle">pause up to MTFA (CSTS.PP)</text><line class="lnd" x1="510" y1="240" x2="548.0" y2="240.0"/><polygon class="ahd" points="556.0,240.0 547.0,244.5 547.0,235.5"/><line class="lna" x1="510" y1="302" x2="548.0" y2="302.0"/><polygon class="ah" points="556.0,302.0 547.0,306.5 547.0,297.5"/><line class="lng" x1="510" y1="376" x2="548.0" y2="376.0"/><polygon class="ah" points="556.0,376.0 547.0,380.5 547.0,371.5"/><text class="xs d" x="380" y="438" text-anchor="middle">A Success status on Commit does not prove activation: read the slot log and FR after the reset.</text></svg>`};
DIAGRAMS.nsmodel={title:'Subsystem, controllers and namespaces',cap:'Namespaces live in the subsystem and are attached to zero or more controllers. Blue lines are private attachments, green lines are the two attachments of a shared namespace.',svg:`<svg viewBox="0 0 760 440" role="img" aria-label="NVM subsystem with two controllers, private and shared namespaces and attach lines"><title>NVM subsystem with two controllers, private and shared namespaces and attach lines</title><rect class="tl" x="10" y="190" width="96" height="64" rx="6" /><text class="s h" x="58" y="218" text-anchor="middle">Host</text><text class="xs d" x="58" y="234" text-anchor="middle">multipath</text><rect class="grp" x="150" y="12" width="600" height="366" rx="6" /><text class="s h" x="162" y="30" text-anchor="start">NVM subsystem</text><rect class="dl" x="190" y="78" width="140" height="64" rx="6" /><text class="s h" x="260" y="104" text-anchor="middle">Controller 0</text><text class="xs d" x="260" y="122" text-anchor="middle">owns its queues</text><rect class="dl" x="190" y="232" width="140" height="64" rx="6" /><text class="s h" x="260" y="258" text-anchor="middle">Controller 1</text><text class="xs d" x="260" y="276" text-anchor="middle">owns its queues</text><line class="ln" x1="106" y1="212" x2="190" y2="110"/><line class="ln" x1="106" y1="232" x2="190" y2="264"/><text class="xs d" x="126" y="168" text-anchor="middle">path 1</text><text class="xs d" x="126" y="268" text-anchor="middle">path 2</text><rect class="dl" x="500" y="58" width="230" height="46" rx="6" /><text class="s h" x="615" y="78" text-anchor="middle">NS A</text><text class="xs" x="615" y="94" text-anchor="middle">private: 1 controller only</text><rect class="pl" x="500" y="128" width="230" height="46" rx="6" /><text class="s h" x="615" y="148" text-anchor="middle">NS B</text><text class="xs" x="615" y="164" text-anchor="middle">shared: NMIC bit 0 = 1</text><rect class="dl" x="500" y="198" width="230" height="46" rx="6" /><text class="s h" x="615" y="218" text-anchor="middle">NS C</text><text class="xs" x="615" y="234" text-anchor="middle">private: 1 controller only</text><rect class="box" x="500" y="268" width="230" height="46" rx="6" /><text class="s h" x="615" y="288" text-anchor="middle">NS D</text><text class="xs" x="615" y="304" text-anchor="middle">created, attached to none</text><line class="lnc" x1="330" y1="100" x2="500" y2="81"/><line class="lng" x1="330" y1="118" x2="500" y2="151"/><line class="lng" x1="330" y1="250" x2="500" y2="165"/><line class="lnc" x1="330" y1="270" x2="500" y2="221"/><rect class="pl" x="190" y="326" width="540" height="40" rx="6" /><text class="s h" x="460" y="343" text-anchor="middle">Non-volatile media</text><text class="xs d" x="460" y="358" text-anchor="middle">namespaces are logical views of it, not NAND slices</text><text class="xs d" x="380" y="398" text-anchor="middle">Each line is one controller-to-namespace attachment. Private: exactly one line. Shared: two or more.</text><text class="xs d" x="380" y="413" text-anchor="middle">The host sees NS B through both controllers, so it must report the same NGUID or EUI64 on both.</text><text class="xs d" x="380" y="428" text-anchor="middle">Attaching a private namespace to a second controller fails: Namespace Is Private (SCT 1, SC 19h).</text></svg>`};
DIAGRAMS.pifmt={title:'The 8-byte protection information tuple',cap:'Guard, Application Tag and Reference Tag make up 8 bytes per LBA. It is generated on the host (or by the controller with PRACT), verified by the controller when PRCHK asks, and verified again by the host on reads.',svg:`<svg viewBox="0 0 760 436" role="img" aria-label="Layout of the 8-byte PI tuple and the write and read path where it is generated and checked"><title>Layout of the 8-byte PI tuple and the write and read path where it is generated and checked</title><text class="xs f" x="100.0" y="16" text-anchor="middle">byte 0</text><text class="xs f" x="180.0" y="16" text-anchor="middle">byte 1</text><text class="xs f" x="260.0" y="16" text-anchor="middle">byte 2</text><text class="xs f" x="340.0" y="16" text-anchor="middle">byte 3</text><text class="xs f" x="420.0" y="16" text-anchor="middle">byte 4</text><text class="xs f" x="500.0" y="16" text-anchor="middle">byte 5</text><text class="xs f" x="580.0" y="16" text-anchor="middle">byte 6</text><text class="xs f" x="660.0" y="16" text-anchor="middle">byte 7</text><rect class="dl" x="60" y="24" width="160" height="44" rx="6" /><text class="s h" x="140.0" y="44" text-anchor="middle">Guard</text><text class="xs d" x="140.0" y="59" text-anchor="middle">16 bits</text><rect class="pl" x="220" y="24" width="160" height="44" rx="6" /><text class="s h" x="300.0" y="44" text-anchor="middle">Application Tag</text><text class="xs d" x="300.0" y="59" text-anchor="middle">16 bits</text><rect class="tl" x="380" y="24" width="320" height="44" rx="6" /><text class="s h" x="540.0" y="44" text-anchor="middle">Reference Tag</text><text class="xs d" x="540.0" y="59" text-anchor="middle">32 bits</text><text class="s h" x="50" y="50" text-anchor="end">PI</text><rect class="box" x="60" y="76" width="160" height="66" rx="6" /><text class="xs" x="140.0" y="94" text-anchor="middle">CRC-16 T10-DIF</text><text class="xs" x="140.0" y="108" text-anchor="middle">poly 0x8BB7, initial 0</text><text class="xs" x="140.0" y="122" text-anchor="middle">over the block data</text><text class="xs" x="140.0" y="136" text-anchor="middle">enabled by PRCHK bit 2</text><rect class="box" x="220" y="76" width="160" height="66" rx="6" /><text class="xs" x="300.0" y="94" text-anchor="middle">host-owned tag</text><text class="xs" x="300.0" y="108" text-anchor="middle">compared under mask (LBATM)</text><text class="xs" x="300.0" y="122" text-anchor="middle">0xFFFF skips the check</text><text class="xs" x="300.0" y="136" text-anchor="middle">enabled by PRCHK bit 1</text><rect class="box" x="380" y="76" width="320" height="66" rx="6" /><text class="xs" x="540.0" y="94" text-anchor="middle">type dependent</text><text class="xs" x="540.0" y="108" text-anchor="middle">Type 1: low 32 bits of the LBA</text><text class="xs" x="540.0" y="122" text-anchor="middle">enabled by PRCHK bit 0</text><text class="xs d" x="380" y="160" text-anchor="middle">All three fields are big-endian, unlike the little-endian SQE and CQE. PI sits in the first or last 8 bytes of the metadata.</text><text class="s h" x="380" y="192" text-anchor="middle">Where the tuple is generated and checked</text><rect class="tl" x="10" y="204" width="190" height="76" rx="6" /><text class="s h" x="105.0" y="221" text-anchor="middle">Host: generate PI</text><text class="xs" x="105.0" y="236" text-anchor="middle">application, block layer</text><text class="xs" x="105.0" y="249" text-anchor="middle">or HBA (or the controller</text><text class="xs" x="105.0" y="262" text-anchor="middle">itself, with PRACT)</text><rect class="dl" x="290" y="204" width="190" height="76" rx="6" /><text class="s h" x="385.0" y="221" text-anchor="middle">Controller: write</text><text class="xs" x="385.0" y="236" text-anchor="middle">verify Guard and tags</text><text class="xs" x="385.0" y="249" text-anchor="middle">when PRCHK asks</text><text class="xs" x="385.0" y="262" text-anchor="middle">(or generate with PRACT)</text><rect class="dl" x="290" y="300" width="190" height="62" rx="6" /><text class="s h" x="385.0" y="317" text-anchor="middle">Controller: read</text><text class="xs" x="385.0" y="332" text-anchor="middle">verify Guard and tags</text><text class="xs" x="385.0" y="345" text-anchor="middle">when PRCHK asks</text><rect class="tl" x="10" y="300" width="190" height="62" rx="6" /><text class="s h" x="105.0" y="317" text-anchor="middle">Host: verify PI</text><text class="xs" x="105.0" y="332" text-anchor="middle">checks what comes back</text><rect class="pl" x="570" y="204" width="180" height="158" rx="6" /><text class="s h" x="660" y="268" text-anchor="middle">Media</text><text class="xs" x="660" y="284" text-anchor="middle">block data plus</text><text class="xs" x="660" y="297" text-anchor="middle">metadata with PI</text><line class="lna" x1="200" y1="242" x2="282.0" y2="242.0"/><polygon class="ah" points="290.0,242.0 281.0,246.5 281.0,237.5"/><text class="xs d" x="245" y="234" text-anchor="middle">PCIe</text><line class="lna" x1="480" y1="242" x2="562.0" y2="242.0"/><polygon class="ah" points="570.0,242.0 561.0,246.5 561.0,237.5"/><line class="lnc" x1="570" y1="331" x2="488.0" y2="331.0"/><polygon class="ahc" points="480.0,331.0 489.0,326.5 489.0,335.5"/><line class="lnc" x1="290" y1="331" x2="208.0" y2="331.0"/><polygon class="ahc" points="200.0,331.0 209.0,326.5 209.0,335.5"/><text class="xs d" x="245" y="323" text-anchor="middle">PCIe</text><text class="xs d" x="380" y="293" text-anchor="middle">write path above, read path below</text><rect class="er" x="10" y="378" width="740" height="44" rx="6" /><text class="s h" x="380" y="396" text-anchor="middle">A mismatch completes with a Guard, Application Tag or Reference Tag Check Error.</text><text class="xs" x="380" y="412" text-anchor="middle">The same tuple travels host to drive and back, so any layer that corrupts the block or its address breaks the match.</text></svg>`};
DIAGRAMS.cqestatus={title:'CQE DW3: the status field',cap:'The 16-byte CQE ends with DW3. Bits 31:17 are the status field (DNR, M, CRD, SCT, SC), bit 16 is the Phase Tag and bits 15:0 are the command identifier.',svg:`<svg viewBox="0 0 760 436" role="img" aria-label="Bit layout of the 16-byte CQE with DW3 status field bit positions"><title>Bit layout of the 16-byte CQE with DW3 status field bit positions</title><text class="xs f" x="55" y="14" text-anchor="middle">31</text><text class="xs f" x="737" y="14" text-anchor="middle">0</text><text class="s h" x="6" y="40" text-anchor="start">DW0</text><rect class="box" x="44" y="22" width="704" height="26" rx="2" /><text class="xs" x="396.0" y="39.0" text-anchor="middle">Command specific result</text><text class="s h" x="6" y="70" text-anchor="start">DW1</text><rect class="box" x="44" y="52" width="704" height="26" rx="2" /><text class="xs" x="396.0" y="69.0" text-anchor="middle">Reserved</text><text class="s h" x="6" y="100" text-anchor="start">DW2</text><rect class="box" x="44" y="82" width="352" height="26" rx="2" /><text class="xs" x="220.0" y="99.0" text-anchor="middle">SQ Identifier (SQID)</text><rect class="box" x="396" y="82" width="352" height="26" rx="2" /><text class="xs" x="572.0" y="99.0" text-anchor="middle">SQ Head Pointer (SQHD)</text><text class="s h ac" x="6" y="168" text-anchor="start">DW3</text><rect class="er" x="44" y="138" width="22" height="52" rx="2" /><text class="xs h" x="55.0" y="132" text-anchor="middle">DNR</text><text class="xs d" x="55.0" y="168.0" text-anchor="middle">31</text><rect class="dl" x="66" y="138" width="22" height="52" rx="2" /><text class="xs h" x="77.0" y="132" text-anchor="middle">M</text><text class="xs d" x="77.0" y="168.0" text-anchor="middle">30</text><rect class="dl" x="88" y="138" width="44" height="52" rx="2" /><text class="s h" x="110.0" y="160" text-anchor="middle">CRD</text><text class="xs d" x="110.0" y="176" text-anchor="middle">29:28</text><rect class="pl" x="132" y="138" width="66" height="52" rx="2" /><text class="s h" x="165.0" y="160" text-anchor="middle">SCT</text><text class="xs d" x="165.0" y="176" text-anchor="middle">27:25</text><rect class="pl" x="198" y="138" width="176" height="52" rx="2" /><text class="s h" x="286.0" y="160" text-anchor="middle">SC</text><text class="xs d" x="286.0" y="176" text-anchor="middle">24:17</text><rect class="tl" x="374" y="138" width="22" height="52" rx="2" /><text class="xs h" x="385.0" y="132" text-anchor="middle">P</text><text class="xs d" x="385.0" y="168.0" text-anchor="middle">16</text><rect class="box" x="396" y="138" width="352" height="52" rx="2" /><text class="s h" x="572.0" y="160" text-anchor="middle">CID</text><text class="xs d" x="572.0" y="176" text-anchor="middle">15:0</text><line class="ln" x1="44" y1="208" x2="396" y2="208"/><line class="ln" x1="44" y1="202" x2="44" y2="208"/><line class="ln" x1="396" y1="202" x2="396" y2="208"/><text class="s ac" x="220.0" y="228" text-anchor="middle">Status field + P: DW3 bits 31:16</text><line class="ln" x1="396" y1="208" x2="748" y2="208"/><line class="ln" x1="396" y1="202" x2="396" y2="208"/><line class="ln" x1="748" y1="202" x2="748" y2="208"/><text class="s " x="572.0" y="228" text-anchor="middle">Command Identifier: DW3 bits 15:0</text><rect class="er" x="10" y="234" width="14" height="14" rx="2" /><text class="s h" x="34" y="245" text-anchor="start">DNR</text><text class="xs d" x="84" y="245" text-anchor="start">31</text><text class="xs" x="136" y="245" text-anchor="start">Do Not Retry</text><rect class="dl" x="10" y="253" width="14" height="14" rx="2" /><text class="s h" x="34" y="264" text-anchor="start">M</text><text class="xs d" x="84" y="264" text-anchor="start">30</text><text class="xs" x="136" y="264" text-anchor="start">More information is in the Error Information log page</text><rect class="dl" x="10" y="272" width="14" height="14" rx="2" /><text class="s h" x="34" y="283" text-anchor="start">CRD</text><text class="xs d" x="84" y="283" text-anchor="start">29:28</text><text class="xs" x="136" y="283" text-anchor="start">Command Retry Delay: index of a retry delay time, 0 means none</text><rect class="pl" x="10" y="291" width="14" height="14" rx="2" /><text class="s h" x="34" y="302" text-anchor="start">SCT</text><text class="xs d" x="84" y="302" text-anchor="start">27:25</text><text class="xs" x="136" y="302" text-anchor="start">0 generic, 1 command specific, 2 media and data integrity, 3 path related, 7 vendor specific</text><rect class="pl" x="10" y="310" width="14" height="14" rx="2" /><text class="s h" x="34" y="321" text-anchor="start">SC</text><text class="xs d" x="84" y="321" text-anchor="start">24:17</text><text class="xs" x="136" y="321" text-anchor="start">Status Code, looked up in the table chosen by SCT</text><rect class="tl" x="10" y="329" width="14" height="14" rx="2" /><text class="s h" x="34" y="340" text-anchor="start">P</text><text class="xs d" x="84" y="340" text-anchor="start">16</text><text class="xs" x="136" y="340" text-anchor="start">Phase Tag, inverts on every pass through the CQ</text><rect class="box" x="10" y="348" width="14" height="14" rx="2" /><text class="s h" x="34" y="359" text-anchor="start">CID</text><text class="xs d" x="84" y="359" text-anchor="start">15:0</text><text class="xs" x="136" y="359" text-anchor="start">Command identifier of the completed command</text><text class="xs d" x="380" y="392" text-anchor="middle">Success is SCT 0 and SC 0. P is 1 on the first pass, so a valid DW3 is never all zero: mask P out before testing.</text><text class="xs d" x="380" y="407" text-anchor="middle">Linux shifts the status right by 1 (drops P): SC in bits 7:0, SCT 10:8, CRD 12:11, M bit 13, DNR bit 14.</text><text class="xs d" x="380" y="422" text-anchor="middle">The status field is meaningless until P matches the phase the host expects for that pass of the CQ.</text></svg>`};
DIAGRAMS.nvmereset={title:'Which reset clears what',cap:'Five triggers against scope, NVMe state, PCIe config and link, and what the host must redo. NVMe state is cleared by every trigger. The NSSR link cell is device dependent, and whether PERST# counts as an NSSR is a spec mapping to VERIFY.',svg:`<svg viewBox="0 0 760 440" role="img" aria-label="Matrix of reset triggers against scope and what each preserves or clears"><title>Matrix of reset triggers against scope and what each preserves or clears</title><rect class="box" x="10" y="8" width="140" height="40" rx="4" /><text class="s h" x="80.0" y="32" text-anchor="middle">Trigger</text><rect class="box" x="156" y="8" width="110" height="40" rx="4" /><text class="s h" x="211.0" y="32" text-anchor="middle">Scope</text><rect class="box" x="272" y="8" width="90" height="40" rx="4" /><text class="s h" x="317.0" y="24" text-anchor="middle">NVMe regs,</text><text class="s h" x="317.0" y="38" text-anchor="middle">queues, I/O</text><rect class="box" x="368" y="8" width="160" height="40" rx="4" /><text class="s h" x="448.0" y="24" text-anchor="middle">PCIe config</text><text class="s h" x="448.0" y="38" text-anchor="middle">and link</text><rect class="box" x="534" y="8" width="216" height="40" rx="4" /><text class="s h" x="642.0" y="24" text-anchor="middle">Host must</text><text class="s h" x="642.0" y="38" text-anchor="middle">redo</text><rect class="box" x="10" y="54" width="140" height="50" rx="4" /><text class="s h" x="80" y="71" text-anchor="middle">CC.EN 1 to 0</text><text class="xs d" x="80" y="85" text-anchor="middle">controller level</text><rect class="box" x="156" y="54" width="110" height="50" rx="4" /><text class="s" x="211.0" y="83.0" text-anchor="middle">One controller</text><rect class="tl" x="272" y="54" width="90" height="50" rx="4" /><text class="s" x="317.0" y="83.0" text-anchor="middle">Cleared</text><rect class="pl" x="368" y="54" width="160" height="50" rx="4" /><text class="s" x="448.0" y="83.0" text-anchor="middle">Kept</text><rect class="box" x="534" y="54" width="216" height="50" rx="4" /><text class="xs" x="642.0" y="83.0" text-anchor="middle">AQA, ASQ, ACQ, CC, then queues</text><rect class="box" x="10" y="108" width="140" height="50" rx="4" /><text class="s h" x="80" y="125" text-anchor="middle">FLR</text><text class="xs d" x="80" y="139" text-anchor="middle">PCIe reset,</text><text class="xs d" x="80" y="150" text-anchor="middle">controller level</text><rect class="box" x="156" y="108" width="110" height="50" rx="4" /><text class="s" x="211.0" y="137.0" text-anchor="middle">One function</text><rect class="tl" x="272" y="108" width="90" height="50" rx="4" /><text class="s" x="317.0" y="137.0" text-anchor="middle">Cleared</text><rect class="tl" x="368" y="108" width="160" height="50" rx="4" /><text class="s" x="448.0" y="137.0" text-anchor="middle">Config reset</text><rect class="box" x="534" y="108" width="216" height="50" rx="4" /><text class="xs" x="642.0" y="137.0" text-anchor="middle">Restore config, then init</text><rect class="box" x="10" y="162" width="140" height="50" rx="4" /><text class="s h" x="80" y="179" text-anchor="middle">Hot reset</text><text class="xs d" x="80" y="193" text-anchor="middle">PCIe reset,</text><text class="xs d" x="80" y="204" text-anchor="middle">controller level</text><rect class="box" x="156" y="162" width="110" height="50" rx="4" /><text class="s" x="211.0" y="191.0" text-anchor="middle">The device</text><rect class="tl" x="272" y="162" width="90" height="50" rx="4" /><text class="s" x="317.0" y="191.0" text-anchor="middle">Cleared</text><rect class="tl" x="368" y="162" width="160" height="50" rx="4" /><text class="s" x="448.0" y="191.0" text-anchor="middle">Reset, link retrains</text><rect class="box" x="534" y="162" width="216" height="50" rx="4" /><text class="xs" x="642.0" y="191.0" text-anchor="middle">Re-enumerate, then init</text><rect class="box" x="10" y="216" width="140" height="50" rx="4" /><text class="s h" x="80" y="233" text-anchor="middle">NSSR</text><text class="xs d" x="80" y="247" text-anchor="middle">subsystem level</text><rect class="box" x="156" y="216" width="110" height="50" rx="4" /><text class="s" x="211.0" y="245.0" text-anchor="middle">All controllers</text><rect class="tl" x="272" y="216" width="90" height="50" rx="4" /><text class="s" x="317.0" y="245.0" text-anchor="middle">Cleared</text><rect class="grp" x="368" y="216" width="160" height="50" rx="4" /><text class="s h" x="448" y="238" text-anchor="middle">Device dependent</text><text class="xs d" x="448" y="253" text-anchor="middle">link drop: VERIFY</text><rect class="box" x="534" y="216" width="216" height="50" rx="4" /><text class="xs" x="642.0" y="245.0" text-anchor="middle">Check NSSRO, maybe re-enumerate</text><rect class="box" x="10" y="270" width="140" height="50" rx="4" /><text class="s h" x="80" y="287" text-anchor="middle">PERST# / power cycle</text><text class="xs d" x="80" y="301" text-anchor="middle">subsystem level,</text><text class="xs d" x="80" y="312" text-anchor="middle">NSSR mapping: VERIFY</text><rect class="box" x="156" y="270" width="110" height="50" rx="4" /><text class="s" x="211.0" y="299.0" text-anchor="middle">Whole subsystem</text><rect class="tl" x="272" y="270" width="90" height="50" rx="4" /><text class="s" x="317.0" y="299.0" text-anchor="middle">Cleared</text><rect class="tl" x="368" y="270" width="160" height="50" rx="4" /><text class="s" x="448.0" y="299.0" text-anchor="middle">Fully reset</text><rect class="box" x="534" y="270" width="216" height="50" rx="4" /><text class="xs" x="642.0" y="299.0" text-anchor="middle">Full enumeration and init</text><rect class="pl" x="10" y="328" width="242" height="84" rx="5" /><text class="s h" x="131" y="344" text-anchor="middle">Survives every trigger</text><text class="xs" x="131" y="360" text-anchor="middle">NAND contents, namespaces and</text><text class="xs" x="131" y="372" text-anchor="middle">attachments, saved feature values,</text><text class="xs" x="131" y="384" text-anchor="middle">persistent logs. Unsaved feature</text><text class="xs" x="131" y="396" text-anchor="middle">values return to defaults.</text><rect class="tl" x="259" y="328" width="242" height="84" rx="5" /><text class="s h" x="380" y="344" text-anchor="middle">Commands in flight</text><text class="xs" x="380" y="360" text-anchor="middle">No CQE arrives. The host completes</text><text class="xs" x="380" y="372" text-anchor="middle">them itself. Acknowledged writes</text><text class="xs" x="380" y="384" text-anchor="middle">should survive. An in-flight write</text><text class="xs" x="380" y="396" text-anchor="middle">is old or new data, never a mix.</text><rect class="dl" x="508" y="328" width="242" height="84" rx="5" /><text class="s h" x="629" y="344" text-anchor="middle">Telling them apart</text><text class="xs" x="629" y="360" text-anchor="middle">NSSR: CSTS.NSSRO set (write 1 to</text><text class="xs" x="629" y="372" text-anchor="middle">clear), Power Cycles unchanged.</text><text class="xs" x="629" y="384" text-anchor="middle">CC.EN toggle: only RDY moved. Wait</text><text class="xs" x="629" y="396" text-anchor="middle">for RDY = 0 (CAP.TO x 500 ms).</text><text class="xs d" x="10" y="430" text-anchor="start">Green = kept or preserved, amber = cleared or reset, dashed = device dependent. No trigger erases NAND data.</text></svg>`};
DIAGRAMS.intpath={title:'A completion from CQE to CPU',cap:'Blue = controller side, amber = host side. The controller writes the CQE first and only then decides whether and when to signal. Timeline: the vector write waits for the threshold or the timer (values from 10.06; the algorithm is vendor specific).',svg:`<svg viewBox="0 0 760 514" role="img" aria-label="Path of a completion from SQ to CQ to MSI-X vector to CPU, with a coalescing timeline"><title>Path of a completion from SQ to CQ to MSI-X vector to CPU, with a coalescing timeline</title><rect class="grp" x="6" y="6" width="748" height="94" rx="6" /><text class="xs d" x="14" y="18" text-anchor="start">Controller firmware: steps 1 to 3 (NAND read done, SQE was taken from the SQ)</text><rect class="grp" x="6" y="104" width="748" height="102" rx="6" /><text class="xs d" x="14" y="116" text-anchor="start">Host memory</text><rect class="grp" x="6" y="210" width="748" height="94" rx="6" /><text class="xs d" x="14" y="222" text-anchor="start">Host driver on the CPU: steps 4 to 6</text><rect class="dl" x="14" y="26" width="136" height="68" rx="5" /><text class="s h" x="82.0" y="42" text-anchor="middle">1 Post CQE</text><text class="xs" x="82.0" y="56" text-anchor="middle">16 B posted write,</text><text class="xs" x="82.0" y="68" text-anchor="middle">phase tag set,</text><text class="xs" x="82.0" y="80" text-anchor="middle">CQ tail advances</text><rect class="dl" x="162" y="26" width="136" height="68" rx="5" /><text class="s h" x="230.0" y="42" text-anchor="middle">2 Decide</text><text class="xs" x="230.0" y="56" text-anchor="middle">checks CQ IEN, IV,</text><text class="xs" x="230.0" y="68" text-anchor="middle">mask, coalescing</text><text class="xs" x="230.0" y="80" text-anchor="middle">(see 10.05)</text><rect class="dl" x="310" y="26" width="136" height="68" rx="5" /><text class="s h" x="378.0" y="42" text-anchor="middle">3 Signal</text><text class="xs" x="378.0" y="56" text-anchor="middle">one posted write to</text><text class="xs" x="378.0" y="68" text-anchor="middle">the vector address;</text><text class="xs" x="378.0" y="80" text-anchor="middle">no queue, CID, data</text><rect class="dl" x="458" y="26" width="136" height="68" rx="5" /><text class="s h" x="526.0" y="42" text-anchor="middle">CQ Head Doorbell</text><text class="xs" x="526.0" y="56" text-anchor="middle">BAR0 register, frees</text><text class="xs" x="526.0" y="68" text-anchor="middle">CQ slots. SQ slots</text><text class="xs" x="526.0" y="80" text-anchor="middle">free via SQ Head Ptr</text><rect class="tl" x="310" y="232" width="136" height="68" rx="5" /><text class="s h" x="378.0" y="248" text-anchor="middle">4 Deliver</text><text class="xs" x="378.0" y="262" text-anchor="middle">ISR runs on the</text><text class="xs" x="378.0" y="274" text-anchor="middle">vector CPU: reads CQE</text><text class="xs" x="378.0" y="286" text-anchor="middle">at head, checks phase</text><rect class="tl" x="458" y="232" width="136" height="68" rx="5" /><text class="s h" x="526.0" y="248" text-anchor="middle">5 Drain, ack</text><text class="xs" x="526.0" y="262" text-anchor="middle">repeat until phase</text><text class="xs" x="526.0" y="274" text-anchor="middle">differs, then ONE</text><text class="xs" x="526.0" y="286" text-anchor="middle">CQ Head DB write</text><rect class="tl" x="606" y="232" width="136" height="68" rx="5" /><text class="s h" x="674.0" y="248" text-anchor="middle">6 Finish</text><text class="xs" x="674.0" y="262" text-anchor="middle">complete by CID,</text><text class="xs" x="674.0" y="274" text-anchor="middle">blk-mq ends request,</text><text class="xs" x="674.0" y="286" text-anchor="middle">task is woken</text><text class="xs d" x="612" y="40" text-anchor="start">CQE first, then the</text><text class="xs d" x="612" y="52" text-anchor="start">vector write. The</text><text class="xs d" x="612" y="64" text-anchor="start">interrupt is only a</text><text class="xs d" x="612" y="76" text-anchor="start">hint that it is there.</text><line class="lnc" x1="150" y1="60" x2="154.0" y2="60.0"/><polygon class="ahc" points="162.0,60.0 153.0,64.5 153.0,55.5"/><line class="lnc" x1="298" y1="60" x2="302.0" y2="60.0"/><polygon class="ahc" points="310.0,60.0 301.0,64.5 301.0,55.5"/><line class="lna" x1="446" y1="266" x2="450.0" y2="266.0"/><polygon class="ah" points="458.0,266.0 449.0,270.5 449.0,261.5"/><line class="lna" x1="594" y1="266" x2="598.0" y2="266.0"/><polygon class="ah" points="606.0,266.0 597.0,270.5 597.0,261.5"/><line class="lnc" x1="378.0" y1="94" x2="378.0" y2="224.0"/><polygon class="ahc" points="378.0,232.0 373.5,223.0 382.5,223.0"/><text class="xs cy" x="386.0" y="144" text-anchor="start">vector write</text><text class="xs cy" x="386.0" y="156" text-anchor="start">(posted)</text><line class="lna" x1="526.0" y1="232" x2="526.0" y2="102.0"/><polygon class="ah" points="526.0,94.0 530.5,103.0 521.5,103.0"/><text class="xs ac" x="534.0" y="150" text-anchor="start">one DB write</text><rect class="dl" x="18" y="138" width="20" height="18" rx="2" /><rect class="dl" x="38" y="138" width="20" height="18" rx="2" /><rect class="dl" x="58" y="138" width="20" height="18" rx="2" /><rect class="box" x="78" y="138" width="20" height="18" rx="2" /><rect class="box" x="98" y="138" width="20" height="18" rx="2" /><rect class="box" x="118" y="138" width="20" height="18" rx="2" /><rect class="box" x="138" y="138" width="20" height="18" rx="2" /><rect class="box" x="158" y="138" width="20" height="18" rx="2" /><text class="xs ac" x="28.0" y="133" text-anchor="middle">head</text><text class="xs cy" x="88.0" y="168" text-anchor="middle">tail</text><line class="lnc" x1="88.0" y1="94" x2="88.0" y2="130.0"/><polygon class="ahc" points="88.0,138.0 83.5,129.0 92.5,129.0"/><text class="xs d" x="188" y="146" text-anchor="start">CQ ring of 16 B CQEs. Each has</text><text class="xs d" x="188" y="158" text-anchor="start">DW0, SQ Head Ptr, SQ ID,</text><text class="xs d" x="188" y="170" text-anchor="start">CID, phase bit, status</text><polyline class="lna" points="310,266 28.0,266 28.0,164.0"/><polygon class="ah" points="28.0,156.0 32.5,165.0 23.5,165.0"/><text class="xs ac" x="48" y="260" text-anchor="start">ISR reads CQEs from head</text><rect class="tl" x="640" y="138" width="22" height="18" rx="2" /><rect class="tl" x="662" y="138" width="22" height="18" rx="2" /><rect class="tl" x="684" y="138" width="22" height="18" rx="2" /><rect class="box" x="706" y="138" width="22" height="18" rx="2" /><text class="xs d" x="684" y="170" text-anchor="middle">SQ ring of 64 B SQEs</text><text class="xs d" x="684" y="182" text-anchor="middle">freed by SQ Head Ptr</text><text class="xs d" x="14" y="320" text-anchor="start">Several CQs may share one vector. The message carries only the vector, so the ISR scans every CQ mapped to it.</text><text class="s h" x="10" y="346" text-anchor="start">Step 2 in time: example THR 3 (4 entries) and TIME 1 (100 us), one CQE every 20 us</text><text class="xs h" x="10" y="368" text-anchor="start">Threshold hit</text><text class="xs d" x="10" y="380" text-anchor="start">4 CQEs in a burst</text><line class="ln" x1="142" y1="376" x2="732.4" y2="376"/><rect class="dl" x="145.0" y="358" width="10" height="18" rx="2" /><rect class="dl" x="249.0" y="358" width="10" height="18" rx="2" /><rect class="dl" x="353.0" y="358" width="10" height="18" rx="2" /><rect class="dl" x="457.0" y="358" width="10" height="18" rx="2" /><line class="lnd" x1="150.0" y1="380" x2="462.0" y2="380"/><line class="lna" x1="462.0" y1="404" x2="462.0" y2="388.0"/><polygon class="ah" points="462.0,380.0 466.5,389.0 457.5,389.0"/><text class="xs ac" x="472.0" y="398" text-anchor="start">MSI-X write at 60 us: 4th CQE reached THR</text><text class="xs h" x="10" y="422" text-anchor="start">Timer hit</text><text class="xs d" x="10" y="434" text-anchor="start">a lone CQE</text><line class="ln" x1="142" y1="430" x2="732.4" y2="430"/><rect class="dl" x="145.0" y="412" width="10" height="18" rx="2" /><line class="lnd" x1="150.0" y1="434" x2="670.0" y2="434"/><line class="lna" x1="670.0" y1="458" x2="670.0" y2="442.0"/><polygon class="ah" points="670.0,434.0 674.5,443.0 665.5,443.0"/><text class="xs ac" x="660.0" y="452" text-anchor="end">MSI-X write at 100 us: TIME ran out</text><line class="ln" x1="150.0" y1="470" x2="732.4" y2="470"/><line class="ln" x1="150.0" y1="470" x2="150.0" y2="475"/><text class="xs d" x="150.0" y="487" text-anchor="middle">0</text><line class="ln" x1="254.0" y1="470" x2="254.0" y2="475"/><text class="xs d" x="254.0" y="487" text-anchor="middle">20</text><line class="ln" x1="358.0" y1="470" x2="358.0" y2="475"/><text class="xs d" x="358.0" y="487" text-anchor="middle">40</text><line class="ln" x1="462.0" y1="470" x2="462.0" y2="475"/><text class="xs d" x="462.0" y="487" text-anchor="middle">60</text><line class="ln" x1="566.0" y1="470" x2="566.0" y2="475"/><text class="xs d" x="566.0" y="487" text-anchor="middle">80</text><line class="ln" x1="670.0" y1="470" x2="670.0" y2="475"/><text class="xs d" x="670.0" y="487" text-anchor="middle">100</text><text class="xs d" x="732.4" y="487" text-anchor="end">us</text><text class="xs d" x="10" y="504" text-anchor="start">Every CQE is already in host memory at its blue box; a polling host sees it there. Only the vector write is held back.</text></svg>`};
DIAGRAMS.nvmepower={title:'APST table and idle timeline',cap:'Rows are the current state, and entry N of the APST table applies in state N. Blue = operational or idle timer, amber = entry or exit latency, green = low-power state. Both timer schemes use the same PS3 and PS4 latencies.',svg:`<svg viewBox="0 0 760 436" role="img" aria-label="Power state and APST target table with an idle timeline"><title>Power state and APST target table with an idle timeline</title><rect class="box" x="10" y="6" width="80" height="38" rx="4" /><text class="s h" x="50.0" y="29" text-anchor="middle">State</text><rect class="box" x="96" y="6" width="200" height="38" rx="4" /><text class="s h" x="196.0" y="21" text-anchor="middle">Descriptor</text><text class="xs d" x="196.0" y="35" text-anchor="middle">ENLAT / EXLAT (total)</text><rect class="box" x="302" y="6" width="210" height="38" rx="4" /><text class="s h" x="407.0" y="21" text-anchor="middle">Recent mainline</text><text class="xs d" x="407.0" y="35" text-anchor="middle">100 ms if total is 15 ms or less</text><rect class="box" x="518" y="6" width="232" height="38" rx="4" /><text class="s h" x="634.0" y="21" text-anchor="middle">Older rule</text><text class="xs d" x="634.0" y="35" text-anchor="middle">idle = 50 x (ENLAT + EXLAT)</text><rect class="box" x="10" y="48" width="80" height="38" rx="4" /><text class="s h" x="50" y="65" text-anchor="middle">PS0-PS2</text><text class="xs d" x="50" y="78" text-anchor="middle">operational</text><rect class="box" x="96" y="48" width="200" height="38" rx="4" /><text class="xs" x="196.0" y="64.5" text-anchor="middle">operational:</text><text class="xs" x="196.0" y="77.5" text-anchor="middle">no ENLAT or EXLAT used</text><rect class="dl" x="302" y="48" width="210" height="38" rx="4" /><text class="s" x="407.0" y="71.0" text-anchor="middle">PS4 after 100 ms</text><rect class="tl" x="518" y="48" width="232" height="38" rx="4" /><text class="s" x="634.0" y="64.5" text-anchor="middle">PS3 after 71 ms</text><text class="xs d" x="634.0" y="77.5" text-anchor="middle">(50 x 1.41 ms)</text><rect class="box" x="10" y="90" width="80" height="38" rx="4" /><text class="s h" x="50" y="107" text-anchor="middle">PS3</text><text class="xs d" x="50" y="120" text-anchor="middle">non-op</text><rect class="box" x="96" y="90" width="200" height="38" rx="4" /><text class="xs" x="196.0" y="113.0" text-anchor="middle">210 us / 1,200 us (1.41 ms)</text><rect class="dl" x="302" y="90" width="210" height="38" rx="4" /><text class="s" x="407.0" y="113.0" text-anchor="middle">PS4 after 100 ms</text><rect class="tl" x="518" y="90" width="232" height="38" rx="4" /><text class="s" x="634.0" y="106.5" text-anchor="middle">PS4 after 500 ms</text><text class="xs d" x="634.0" y="119.5" text-anchor="middle">(50 x 10 ms)</text><rect class="box" x="10" y="132" width="80" height="38" rx="4" /><text class="s h" x="50" y="149" text-anchor="middle">PS4</text><text class="xs d" x="50" y="162" text-anchor="middle">non-op</text><rect class="box" x="96" y="132" width="200" height="38" rx="4" /><text class="xs" x="196.0" y="155.0" text-anchor="middle">1,000 us / 9,000 us (10 ms)</text><rect class="box" x="302" y="132" width="210" height="38" rx="4" /><text class="s" x="407.0" y="155.0" text-anchor="middle">none</text><rect class="box" x="518" y="132" width="232" height="38" rx="4" /><text class="s" x="634.0" y="155.0" text-anchor="middle">none</text><text class="xs d" x="10" y="186" text-anchor="start">PS3 is skipped in the recent scheme: both PS3 and PS4 fall inside the 15 ms primary tolerance, so only the deepest is used.</text><text class="xs d" x="10" y="199" text-anchor="start">A state with total latency between 15 ms and 100 ms would form a second tier with a 2,000 ms timeout.</text><text class="s h" x="10" y="226" text-anchor="start">Idle timeline, PS4 example (ENLAT 1 ms, EXLAT 9 ms), recent scheme. Not to scale after t = 100 ms.</text><rect class="dl" x="30" y="240" width="300" height="38" rx="3" /><text class="s" x="180.0" y="264" text-anchor="middle">PS0, idle timer runs (100 ms)</text><rect class="tl" x="330" y="240" width="42" height="38" rx="3" /><text class="xs h" x="351.0" y="264" text-anchor="middle">ENLAT</text><rect class="pl" x="372" y="240" width="188" height="38" rx="3" /><rect class="tl" x="560" y="240" width="52" height="38" rx="3" /><text class="xs h" x="586.0" y="264" text-anchor="middle">EXLAT</text><rect class="dl" x="612" y="240" width="128" height="38" rx="3" /><text class="s" x="676.0" y="264" text-anchor="middle">operational</text><text class="s h" x="466" y="257" text-anchor="middle">PS4 dwell</text><text class="xs" x="466" y="271" text-anchor="middle">power falls, L1.2 possible</text><line class="lnd" x1="30" y1="278" x2="30" y2="292"/><line class="lnd" x1="330" y1="278" x2="330" y2="292"/><line class="lnd" x1="560" y1="278" x2="560" y2="292"/><text class="xs" x="30" y="304" text-anchor="start">t = 0: last I/O completes,</text><text class="xs" x="30" y="316" text-anchor="start">idle timer starts in PS0</text><text class="xs" x="330" y="304" text-anchor="middle">t = 100 ms: timer expires,</text><text class="xs" x="330" y="316" text-anchor="middle">enter PS4 (up to ENLAT)</text><text class="xs" x="560" y="304" text-anchor="middle">doorbell write arrives,</text><text class="xs" x="560" y="316" text-anchor="middle">exit takes up to EXLAT</text><text class="xs d" x="740" y="332" text-anchor="end">I/O completes after exit plus normal service time</text><text class="s h" x="10" y="356" text-anchor="start">Same drive under the older 50 x rule (PS0 to PS2 start):</text><rect class="dl" x="30" y="366" width="213" height="34" rx="3" /><text class="s" x="136" y="387" text-anchor="middle">PS0, idle 71 ms</text><rect class="pl" x="243" y="366" width="317" height="34" rx="3" /><text class="s h" x="401" y="380" text-anchor="middle">PS3 dwell</text><text class="xs" x="401" y="393" text-anchor="middle">its own timer: PS4 after 500 ms</text><rect class="pl" x="560" y="366" width="180" height="34" rx="3" /><text class="s h" x="650" y="387" text-anchor="middle">PS4</text><line class="lnd" x1="243" y1="400" x2="243" y2="410"/><text class="xs d" x="237" y="422" text-anchor="end">71 ms: enter PS3</text><line class="lnd" x1="330" y1="400" x2="330" y2="410"/><text class="xs d" x="337" y="422" text-anchor="start">100 ms: recent scheme is already in PS4</text></svg>`};
DIAGRAMS.eraseops={title:'Deallocate, Format, Sanitize, crypto erase',cap:'Scope, physical guarantee and power-loss behavior as 12.02 states them. Amber cells are in scope, red = no physical guarantee, green = physical or committed erase. Sanitize is subsystem-wide, Format is per namespace, crypto erase destroys the key and leaves ciphertext.',svg:`<svg viewBox="0 0 760 438" role="img" aria-label="Comparison of Deallocate, Format NVM, Sanitize and crypto erase by scope and guarantee"><title>Comparison of Deallocate, Format NVM, Sanitize and crypto erase by scope and guarantee</title><rect class="box" x="8" y="6" width="138" height="40" rx="4" /><text class="s h" x="77" y="30" text-anchor="middle">Operation</text><rect class="box" x="152" y="6" width="58" height="40" rx="4" /><text class="xs h" x="181.0" y="21" text-anchor="middle">NS 1</text><text class="xs d" x="181.0" y="35" text-anchor="middle">target</text><rect class="box" x="214" y="6" width="58" height="40" rx="4" /><text class="xs h" x="243.0" y="21" text-anchor="middle">NS 2</text><text class="xs d" x="243.0" y="35" text-anchor="middle">other</text><rect class="box" x="276" y="6" width="72" height="40" rx="4" /><text class="xs h" x="312.0" y="21" text-anchor="middle">Unattached</text><text class="xs d" x="312.0" y="35" text-anchor="middle">NS</text><rect class="box" x="352" y="6" width="58" height="40" rx="4" /><text class="xs h" x="381.0" y="30" text-anchor="middle">Caches</text><rect class="box" x="416" y="6" width="190" height="40" rx="4" /><text class="s h" x="511.0" y="30" text-anchor="middle">Physical guarantee</text><rect class="box" x="612" y="6" width="140" height="40" rx="4" /><text class="s h" x="682.0" y="21" text-anchor="middle">Survives</text><text class="s h" x="682.0" y="35" text-anchor="middle">power loss</text><text class="xs" x="277" y="2" text-anchor="middle"></text><rect class="box" x="8" y="52" width="138" height="50" rx="4" /><text class="s h" x="77" y="69" text-anchor="middle">Deallocate</text><text class="xs d" x="77" y="82" text-anchor="middle">Dataset Management</text><rect class="grp" x="152" y="52" width="58" height="50" rx="4" /><text class="xs" x="181.0" y="74" text-anchor="middle">listed</text><text class="xs" x="181.0" y="86" text-anchor="middle">LBAs</text><rect class="box" x="214" y="52" width="58" height="50" rx="4" opacity="0.45"/><rect class="box" x="276" y="52" width="72" height="50" rx="4" opacity="0.45"/><rect class="box" x="352" y="52" width="58" height="50" rx="4" opacity="0.45"/><rect class="er" x="416" y="52" width="190" height="50" rx="4" /><text class="xs h" x="511.0" y="75.0" text-anchor="middle">None, it is a hint</text><text class="xs d" x="511.0" y="87.0" text-anchor="middle">logical: mapping changes</text><rect class="box" x="612" y="52" width="140" height="50" rx="4" /><text class="xs" x="682.0" y="81.0" text-anchor="middle">Not applicable</text><rect class="box" x="8" y="106" width="138" height="50" rx="4" /><text class="s h" x="77" y="123" text-anchor="middle">Format NVM</text><text class="xs d" x="77" y="136" text-anchor="middle">SES=0</text><rect class="tl" x="152" y="106" width="58" height="50" rx="4" /><rect class="grp" x="214" y="106" width="58" height="50" rx="4" /><text class="xs" x="243.0" y="128" text-anchor="middle">if all</text><rect class="box" x="276" y="106" width="72" height="50" rx="4" opacity="0.45"/><rect class="box" x="352" y="106" width="58" height="50" rx="4" opacity="0.45"/><rect class="er" x="416" y="106" width="190" height="50" rx="4" /><text class="xs h" x="511.0" y="129.0" text-anchor="middle">None: layout changes,</text><text class="xs d" x="511.0" y="141.0" text-anchor="middle">data unreachable</text><rect class="grp" x="612" y="106" width="140" height="50" rx="4" /><text class="xs" x="682.0" y="135.0" text-anchor="middle">Vendor specific</text><rect class="box" x="8" y="160" width="138" height="50" rx="4" /><text class="s h" x="77" y="177" text-anchor="middle">Format NVM</text><text class="xs d" x="77" y="190" text-anchor="middle">SES=1 or 2</text><rect class="tl" x="152" y="160" width="58" height="50" rx="4" /><rect class="grp" x="214" y="160" width="58" height="50" rx="4" /><text class="xs" x="243.0" y="182" text-anchor="middle">if FNA</text><text class="xs" x="243.0" y="194" text-anchor="middle">says so</text><rect class="box" x="276" y="160" width="72" height="50" rx="4" opacity="0.45"/><rect class="tl" x="352" y="160" width="58" height="50" rx="4" /><rect class="pl" x="416" y="160" width="190" height="50" rx="4" /><text class="xs h" x="511.0" y="183.0" text-anchor="middle">User data erased, including</text><text class="xs d" x="511.0" y="195.0" text-anchor="middle">caches and deallocated LBAs</text><rect class="grp" x="612" y="160" width="140" height="50" rx="4" /><text class="xs" x="682.0" y="177.0" text-anchor="middle">Test it: spec is less</text><text class="xs" x="682.0" y="189.0" text-anchor="middle">explicit than for</text><text class="xs" x="682.0" y="201.0" text-anchor="middle">Sanitize</text><rect class="box" x="8" y="214" width="138" height="50" rx="4" /><text class="s h" x="77" y="231" text-anchor="middle">Sanitize</text><text class="xs d" x="77" y="244" text-anchor="middle">block erase, overwrite</text><rect class="tl" x="152" y="214" width="58" height="50" rx="4" /><rect class="tl" x="214" y="214" width="58" height="50" rx="4" /><rect class="tl" x="276" y="214" width="72" height="50" rx="4" /><rect class="tl" x="352" y="214" width="58" height="50" rx="4" /><rect class="pl" x="416" y="214" width="190" height="50" rx="4" /><text class="xs h" x="511.0" y="237.0" text-anchor="middle">Media erased or overwritten</text><text class="xs d" x="511.0" y="249.0" text-anchor="middle">physical: changes the media</text><rect class="pl" x="612" y="214" width="140" height="50" rx="4" /><text class="xs" x="682.0" y="237.0" text-anchor="middle">Yes, continues</text><text class="xs" x="682.0" y="249.0" text-anchor="middle">after reset</text><rect class="box" x="8" y="268" width="138" height="50" rx="4" /><text class="s h" x="77" y="285" text-anchor="middle">Crypto erase</text><text class="xs d" x="77" y="298" text-anchor="middle">Sanitize crypto, or</text><text class="xs d" x="77" y="309" text-anchor="middle">Opal Revert / GenKey</text><rect class="tl" x="152" y="268" width="58" height="50" rx="4" /><rect class="tl" x="214" y="268" width="58" height="50" rx="4" /><rect class="tl" x="276" y="268" width="72" height="50" rx="4" /><rect class="tl" x="352" y="268" width="58" height="50" rx="4" /><rect class="pl" x="416" y="268" width="190" height="50" rx="4" /><text class="xs h" x="511.0" y="285.0" text-anchor="middle">Key destroyed, ciphertext</text><text class="xs d" x="511.0" y="297.0" text-anchor="middle">remains but is useless</text><text class="xs d" x="511.0" y="309.0" text-anchor="middle">physical: changes the key</text><rect class="pl" x="612" y="268" width="140" height="50" rx="4" /><text class="xs" x="682.0" y="291.0" text-anchor="middle">Yes, once the key</text><text class="xs" x="682.0" y="303.0" text-anchor="middle">change is committed</text><text class="xs d" x="10" y="332" text-anchor="start">Filled = in scope. Dashed = only if asked for (all namespaces, FNA, listed LBAs). Blank = outside the scope the text gives.</text><text class="xs d" x="10" y="344" text-anchor="start">Opal Revert or GenKey can act on one locking range, not the whole subsystem. SES=0 read-back and secure-erase wording: VERIFY.</text><rect class="dl" x="8" y="356" width="242" height="74" rx="5" /><text class="s h" x="129.0" y="372" text-anchor="middle">Scope first</text><text class="xs" x="129.0" y="388" text-anchor="middle">Format can be limited to one</text><text class="xs" x="129.0" y="400" text-anchor="middle">namespace. Sanitize cannot: on a</text><text class="xs" x="129.0" y="412" text-anchor="middle">drive with two namespaces it</text><text class="xs" x="129.0" y="424" text-anchor="middle">destroys both, attached or not.</text><rect class="pl" x="259" y="356" width="242" height="74" rx="5" /><text class="s h" x="380.0" y="372" text-anchor="middle">Guarantee second</text><text class="xs" x="380.0" y="388" text-anchor="middle">Logical (Deallocate, Format SES=0):</text><text class="xs" x="380.0" y="400" text-anchor="middle">the mapping changes. Physical (block</text><text class="xs" x="380.0" y="412" text-anchor="middle">erase, overwrite, key destruction):</text><text class="xs" x="380.0" y="424" text-anchor="middle">the media or the key changes.</text><rect class="tl" x="510" y="356" width="242" height="74" rx="5" /><text class="s h" x="631.0" y="372" text-anchor="middle">Speed third</text><text class="xs" x="631.0" y="388" text-anchor="middle">Crypto erase takes seconds, block</text><text class="xs" x="631.0" y="400" text-anchor="middle">erase seconds to minutes, overwrite</text><text class="xs" x="631.0" y="412" text-anchor="middle">hours. Zero reads prove less than</text><text class="xs" x="631.0" y="424" text-anchor="middle">you think: see the Trap question.</text></svg>`};
DIAGRAMS.multictrl={title:'Dual-port SSD, two controllers',cap:'Amber = host, blue = per-controller state, green = shared by the whole subsystem. Queues, doorbells and interrupts belong to one controller. Media, namespaces and NQN are shared, and CNTLID is unique only inside this subsystem.',svg:`<svg viewBox="0 0 760 460" role="img" aria-label="Two hosts, two controllers and shared and private namespaces in one NVM subsystem"><title>Two hosts, two controllers and shared and private namespaces in one NVM subsystem</title><rect class="grp" x="6" y="92" width="748" height="328" rx="6" /><text class="xs d" x="16" y="106" text-anchor="start">NVM subsystem, one NQN</text><rect class="tl" x="100" y="6" width="190" height="50" rx="5" /><text class="s h" x="195.0" y="22" text-anchor="middle">Host A</text><text class="xs" x="195.0" y="38" text-anchor="middle">own driver instance</text><line class="lna" x1="195" y1="56" x2="195" y2="116"/><text class="xs ac" x="203" y="80" text-anchor="start">PCIe link 0 (port 0)</text><rect class="tl" x="470" y="6" width="190" height="50" rx="5" /><text class="s h" x="565.0" y="22" text-anchor="middle">Host B</text><text class="xs" x="565.0" y="38" text-anchor="middle">own driver instance</text><line class="lna" x1="565" y1="56" x2="565" y2="116"/><text class="xs ac" x="573" y="80" text-anchor="start">PCIe link 1 (port 1)</text><rect class="dl" x="50" y="116" width="290" height="110" rx="5" /><text class="s h" x="195.0" y="132" text-anchor="middle">Controller 0, own CNTLID</text><text class="xs" x="195.0" y="148" text-anchor="middle">BAR0: CAP, CC, CSTS, doorbells</text><text class="xs" x="195.0" y="160" text-anchor="middle">admin queue and I/O queues</text><text class="xs" x="195.0" y="172" text-anchor="middle">MSI-X table, Set Features state</text><text class="xs" x="195.0" y="184" text-anchor="middle">AER queue, controller-scoped logs</text><rect class="pl" x="62" y="198" width="266" height="20" rx="3" /><text class="xs" x="195.0" y="212" text-anchor="middle">ANA group 1 seen here: Optimized (01h)</text><rect class="dl" x="420" y="116" width="290" height="110" rx="5" /><text class="s h" x="565.0" y="132" text-anchor="middle">Controller 1, own CNTLID</text><text class="xs" x="565.0" y="148" text-anchor="middle">BAR0: CAP, CC, CSTS, doorbells</text><text class="xs" x="565.0" y="160" text-anchor="middle">admin queue and I/O queues</text><text class="xs" x="565.0" y="172" text-anchor="middle">MSI-X table, Set Features state</text><text class="xs" x="565.0" y="184" text-anchor="middle">AER queue, controller-scoped logs</text><rect class="pl" x="432" y="198" width="266" height="20" rx="3" /><text class="xs" x="565.0" y="212" text-anchor="middle">ANA group 1 seen here: Optimized (01h)</text><rect class="box" x="40" y="290" width="190" height="52" rx="5" /><text class="s h" x="135.0" y="306" text-anchor="middle">NS 1, private</text><text class="xs" x="135.0" y="320" text-anchor="middle">attached to controller 0</text><text class="xs" x="135.0" y="332" text-anchor="middle">only</text><rect class="pl" x="285" y="290" width="190" height="52" rx="5" /><text class="s h" x="380.0" y="306" text-anchor="middle">NS 2, shared</text><text class="xs" x="380.0" y="320" text-anchor="middle">NMIC bit 0 set, attached</text><text class="xs" x="380.0" y="332" text-anchor="middle">to both, ANA group 1</text><rect class="box" x="530" y="290" width="190" height="52" rx="5" /><text class="s h" x="625.0" y="306" text-anchor="middle">NS 3, private</text><text class="xs" x="625.0" y="320" text-anchor="middle">attached to controller 1</text><text class="xs" x="625.0" y="332" text-anchor="middle">only</text><line class="lnc" x1="135" y1="226" x2="135.0" y2="282.0"/><polygon class="ahc" points="135.0,290.0 130.5,281.0 139.5,281.0"/><line class="lnc" x1="300" y1="226" x2="331.2" y2="283.0"/><polygon class="ahc" points="335.0,290.0 326.7,284.3 334.6,279.9"/><line class="lnc" x1="460" y1="226" x2="428.8" y2="283.0"/><polygon class="ahc" points="425.0,290.0 425.4,279.9 433.3,284.3"/><line class="lnc" x1="625" y1="226" x2="625.0" y2="282.0"/><polygon class="ahc" points="625.0,290.0 620.5,281.0 629.5,281.0"/><text class="xs cy" x="305" y="268" text-anchor="end">attach</text><text class="xs cy" x="455" y="268" text-anchor="start">attach</text><rect class="pl" x="40" y="366" width="680" height="42" rx="5" /><text class="xs" x="380" y="383" text-anchor="middle">Shared by all controllers: NAND media and FTL, namespace contents,</text><text class="xs" x="380" y="397" text-anchor="middle">subsystem NQN, reservation state per namespace, NVM Subsystem Reset domain</text><line class="lnd" x1="135" y1="342" x2="135" y2="366"/><line class="lnd" x1="380" y1="342" x2="380" y2="366"/><line class="lnd" x1="625" y1="342" x2="625" y2="366"/><text class="xs d" x="10" y="436" text-anchor="start">ANA state is per (controller, ANA group): Optimized 01h, Non-optimized 02h, Inaccessible 03h, Persistent Loss 04h, Change 0Fh.</text><text class="xs d" x="10" y="449" text-anchor="start">Plain dual-port drive: usually Optimized on both. After a fault one controller can report Inaccessible for the same group.</text></svg>`};
DIAGRAMS.fabrics={title:'NVMe over Fabrics: same commands, new transport',cap:'Amber is the host side, blue the target side. The 64-byte command and 16-byte completion are the same as over PCIe; a capsule simply carries them in a network message, and each queue gets its own Connect. Widths in the capsule strips are not to scale.',svg:`<svg viewBox="0 0 760 456" role="img" aria-label="NVMe over Fabrics path, bring-up sequence and capsule format"><title>NVMe over Fabrics path, bring-up sequence and capsule format</title><text class="s h" x="10" y="18" text-anchor="start">One command: host to backend</text><rect class="tl" x="10" y="34" width="120" height="136" rx="6" /><text class="h" x="70" y="56" text-anchor="middle">Host</text><text class="xs" x="70" y="78" text-anchor="middle">NVMe driver</text><text class="xs" x="70" y="92" text-anchor="middle">fabric transport</text><text class="xs" x="70" y="106" text-anchor="middle">initiator</text><text class="xs d" x="70" y="134" text-anchor="middle">no BAR, no</text><text class="xs d" x="70" y="148" text-anchor="middle">doorbells</text><rect class="grp" x="190" y="34" width="240" height="136" rx="6" /><text class="s h" x="310" y="54" text-anchor="middle">Fabric transport</text><rect class="box" x="200" y="66" width="66" height="50" rx="6" /><text class="s h" x="233" y="96" text-anchor="middle">RDMA</text><rect class="box" x="278" y="66" width="66" height="50" rx="6" /><text class="s h" x="311" y="96" text-anchor="middle">TCP</text><rect class="box" x="356" y="66" width="66" height="50" rx="6" /><text class="s h" x="389" y="87" text-anchor="middle">Fibre</text><text class="s h" x="389" y="102" text-anchor="middle">Channel</text><text class="xs d" x="310" y="140" text-anchor="middle">capsules travel as network</text><text class="xs d" x="310" y="155" text-anchor="middle">messages, not MMIO or DMA</text><line class="lna" x1="130" y1="80" x2="182.0" y2="80.0"/><polygon class="ah" points="190.0,80.0 181.0,84.5 181.0,75.5"/><text class="xs" x="160" y="72" text-anchor="middle">command</text><line class="lnc" x1="190" y1="116" x2="138.0" y2="116.0"/><polygon class="ahc" points="130.0,116.0 139.0,111.5 139.0,120.5"/><text class="xs" x="160" y="134" text-anchor="middle">response</text><line class="lna" x1="430" y1="80" x2="482.0" y2="80.0"/><polygon class="ah" points="490.0,80.0 481.0,84.5 481.0,75.5"/><text class="xs" x="460" y="72" text-anchor="middle">command</text><line class="lnc" x1="490" y1="116" x2="438.0" y2="116.0"/><polygon class="ahc" points="430.0,116.0 439.0,111.5 439.0,120.5"/><text class="xs" x="460" y="134" text-anchor="middle">response</text><rect class="dl" x="490" y="34" width="260" height="100" rx="6" /><text class="s h" x="620" y="54" text-anchor="middle">Target: NVM subsystem</text><rect class="box" x="500" y="66" width="126" height="56" rx="6" /><text class="s h" x="563" y="84" text-anchor="middle">Controller</text><text class="xs d" x="563" y="99" text-anchor="middle">admin + I/O queues</text><text class="xs d" x="563" y="113" text-anchor="middle">one connection each</text><rect class="box" x="636" y="66" width="106" height="56" rx="6" /><text class="s h" x="689" y="88" text-anchor="middle">Namespaces</text><text class="xs d" x="689" y="104" text-anchor="middle">NVM, ZNS sets</text><line class="lnc" x1="620" y1="134" x2="620.0" y2="142.0"/><polygon class="ahc" points="620.0,150.0 615.5,141.0 624.5,141.0"/><rect class="pl" x="490" y="150" width="260" height="84" rx="6" /><text class="s h" x="620" y="168" text-anchor="middle">Backend behind the target</text><text class="xs" x="620" y="184" text-anchor="middle">SSD behind a software target</text><text class="xs" x="620" y="197" text-anchor="middle">array controller</text><text class="xs" x="620" y="210" text-anchor="middle">DPU or bridge in a JBOF/EBOF</text><text class="xs" x="620" y="223" text-anchor="middle">rarely an SSD with a native fabric port</text><text class="s h" x="10" y="262" text-anchor="start">Bring-up before any I/O</text><rect class="tl" x="10" y="270" width="216" height="54" rx="6" /><text class="s h" x="118" y="288" text-anchor="middle">Discovery</text><text class="xs" x="118" y="302" text-anchor="middle">read the discovery log from</text><text class="xs d" x="118" y="315" text-anchor="middle">a discovery controller</text><rect class="tl" x="272" y="270" width="216" height="54" rx="6" /><text class="s h" x="380" y="288" text-anchor="middle">Connect: admin queue</text><text class="xs" x="380" y="302" text-anchor="middle">of the chosen subsystem</text><text class="xs d" x="380" y="315" text-anchor="middle">one connection</text><rect class="tl" x="534" y="270" width="216" height="54" rx="6" /><text class="s h" x="642" y="288" text-anchor="middle">Connect: each I/O queue</text><text class="xs" x="642" y="302" text-anchor="middle">of the same subsystem</text><text class="xs d" x="642" y="315" text-anchor="middle">one connection per queue</text><line class="lna" x1="226" y1="297" x2="264.0" y2="297.0"/><polygon class="ah" points="272.0,297.0 263.0,301.5 263.0,292.5"/><line class="lna" x1="488" y1="297" x2="526.0" y2="297.0"/><polygon class="ah" points="534.0,297.0 525.0,301.5 525.0,292.5"/><text class="s h" x="10" y="346" text-anchor="start">Capsule format (not to scale)</text><text class="s" x="10" y="374" text-anchor="start">Command capsule</text><rect class="tl" x="150" y="354" width="170" height="40" rx="6" /><text class="s h" x="235" y="371" text-anchor="middle">SQE, 64 B</text><text class="xs d" x="235" y="385" text-anchor="middle">the NVMe command</text><rect class="grp" x="320" y="354" width="250" height="40" rx="6" /><text class="s h" x="445" y="371" text-anchor="middle">in-capsule data</text><text class="xs d" x="445" y="385" text-anchor="middle">optional</text><text class="s" x="10" y="428" text-anchor="start">Response capsule</text><rect class="dl" x="150" y="408" width="100" height="40" rx="6" /><text class="s h" x="200" y="425" text-anchor="middle">CQE, 16 B</text><text class="xs d" x="200" y="439" text-anchor="middle">the completion</text><text class="xs d" x="290" y="423" text-anchor="start">Bulk data is not in the capsule. It moves by</text><text class="xs d" x="290" y="437" text-anchor="start">RDMA Read/Write or TCP data PDUs.</text></svg>`};
DIAGRAMS.fdp={title:'FDP: placement identifiers versus mixed writes',cap:'Amber is short-lived (hot) data and blue is long-lived (cold). Without FDP the two interleave in one block and GC copies the cold survivors. With FDP the PID in each write picks a reclaim group and a handle, so each lifetime class lands in its own reclaim unit.',svg:`<svg viewBox="0 0 760 436" role="img" aria-label="Mixed writes in one block versus Flexible Data Placement reclaim groups, reclaim units and handles"><title>Mixed writes in one block versus Flexible Data Placement reclaim groups, reclaim units and handles</title><text class="s h" x="10" y="18" text-anchor="start">Conventional SSD: hot and cold writes share one open block</text><rect class="tl" x="506" y="28" width="12" height="12" rx="2" /><text class="xs" x="526" y="38" text-anchor="start">hot, short-lived data</text><rect class="dl" x="506" y="46" width="12" height="12" rx="2" /><text class="xs" x="526" y="56" text-anchor="start">cold, long-lived data</text><text class="s" x="10" y="56" text-anchor="start">written together</text><rect class="tl" x="150" y="34" width="38" height="30" rx="3" /><text class="s h" x="169" y="54" text-anchor="middle">H</text><rect class="dl" x="192" y="34" width="38" height="30" rx="3" /><text class="s h" x="211" y="54" text-anchor="middle">C</text><rect class="tl" x="234" y="34" width="38" height="30" rx="3" /><text class="s h" x="253" y="54" text-anchor="middle">H</text><rect class="tl" x="276" y="34" width="38" height="30" rx="3" /><text class="s h" x="295" y="54" text-anchor="middle">H</text><rect class="dl" x="318" y="34" width="38" height="30" rx="3" /><text class="s h" x="337" y="54" text-anchor="middle">C</text><rect class="tl" x="360" y="34" width="38" height="30" rx="3" /><text class="s h" x="379" y="54" text-anchor="middle">H</text><rect class="dl" x="402" y="34" width="38" height="30" rx="3" /><text class="s h" x="421" y="54" text-anchor="middle">C</text><rect class="tl" x="444" y="34" width="38" height="30" rx="3" /><text class="s h" x="463" y="54" text-anchor="middle">H</text><text class="s" x="10" y="108" text-anchor="start">after hot data dies</text><rect class="er" x="150" y="86" width="38" height="30" rx="3" /><text class="s d" x="169" y="106" text-anchor="middle">x</text><rect class="dl" x="192" y="86" width="38" height="30" rx="3" /><text class="s h" x="211" y="106" text-anchor="middle">C</text><rect class="er" x="234" y="86" width="38" height="30" rx="3" /><text class="s d" x="253" y="106" text-anchor="middle">x</text><rect class="er" x="276" y="86" width="38" height="30" rx="3" /><text class="s d" x="295" y="106" text-anchor="middle">x</text><rect class="dl" x="318" y="86" width="38" height="30" rx="3" /><text class="s h" x="337" y="106" text-anchor="middle">C</text><rect class="er" x="360" y="86" width="38" height="30" rx="3" /><text class="s d" x="379" y="106" text-anchor="middle">x</text><rect class="dl" x="402" y="86" width="38" height="30" rx="3" /><text class="s h" x="421" y="106" text-anchor="middle">C</text><rect class="er" x="444" y="86" width="38" height="30" rx="3" /><text class="s d" x="463" y="106" text-anchor="middle">x</text><text class="xs d" x="506" y="92" text-anchor="start">garbage collection must copy the</text><text class="xs d" x="506" y="106" text-anchor="start">cold survivors before it can</text><text class="xs d" x="506" y="120" text-anchor="start">erase this block</text><line class="ln" x1="10" y1="138" x2="750" y2="138"/><text class="s h" x="10" y="160" text-anchor="start">FDP (enabled per Endurance Group): the host names a placement identifier</text><text class="s h" x="80" y="190" text-anchor="middle">Write command</text><text class="xs d" x="80" y="204" text-anchor="middle">DTYPE=2, DSPEC=PID</text><rect class="tl" x="10" y="214" width="140" height="54" rx="6" /><text class="s h" x="80" y="234" text-anchor="middle">hot write</text><text class="xs" x="80" y="248" text-anchor="middle">PID 0003h</text><text class="xs d" x="80" y="261" text-anchor="middle">RG0, handle 3</text><rect class="tl" x="10" y="280" width="140" height="54" rx="6" /><text class="s h" x="80" y="300" text-anchor="middle">cold write</text><text class="xs" x="80" y="314" text-anchor="middle">PID 0004h</text><text class="xs d" x="80" y="327" text-anchor="middle">RG0, handle 4</text><text class="s h" x="255" y="190" text-anchor="middle">RUHs</text><text class="xs d" x="255" y="204" text-anchor="middle">point at the open RU</text><rect class="dl" x="195" y="214" width="120" height="54" rx="6" /><text class="s h" x="255" y="236" text-anchor="middle">RUH</text><text class="xs d" x="255" y="252" text-anchor="middle">placement handle 3</text><rect class="dl" x="195" y="280" width="120" height="54" rx="6" /><text class="s h" x="255" y="302" text-anchor="middle">RUH</text><text class="xs d" x="255" y="318" text-anchor="middle">placement handle 4</text><line class="lna" x1="150" y1="241" x2="187.0" y2="241.0"/><polygon class="ah" points="195.0,241.0 186.0,245.5 186.0,236.5"/><line class="lna" x1="150" y1="307" x2="187.0" y2="307.0"/><polygon class="ah" points="195.0,307.0 186.0,311.5 186.0,302.5"/><rect class="grp" x="365" y="174" width="205" height="172" rx="6" /><text class="s h" x="467" y="192" text-anchor="middle">Reclaim group RG0</text><line class="lnc" x1="315" y1="241" x2="372.0" y2="241.0"/><polygon class="ahc" points="380.0,241.0 371.0,245.5 371.0,236.5"/><line class="lnc" x1="315" y1="307" x2="372.0" y2="307.0"/><polygon class="ahc" points="380.0,307.0 371.0,311.5 371.0,302.5"/><rect class="box" x="380" y="214" width="176" height="54" rx="6" /><text class="xs d" x="468" y="229" text-anchor="middle">reclaim unit: hot only</text><rect class="tl" x="390" y="238" width="26" height="20" rx="2" /><text class="xs h" x="403" y="252" text-anchor="middle">H</text><rect class="tl" x="420" y="238" width="26" height="20" rx="2" /><text class="xs h" x="433" y="252" text-anchor="middle">H</text><rect class="tl" x="450" y="238" width="26" height="20" rx="2" /><text class="xs h" x="463" y="252" text-anchor="middle">H</text><rect class="tl" x="480" y="238" width="26" height="20" rx="2" /><text class="xs h" x="493" y="252" text-anchor="middle">H</text><rect class="grp" x="510" y="238" width="36" height="20" rx="2" /><rect class="box" x="380" y="280" width="176" height="54" rx="6" /><text class="xs d" x="468" y="295" text-anchor="middle">reclaim unit: cold only</text><rect class="dl" x="390" y="304" width="26" height="20" rx="2" /><text class="xs h" x="403" y="318" text-anchor="middle">C</text><rect class="dl" x="420" y="304" width="26" height="20" rx="2" /><text class="xs h" x="433" y="318" text-anchor="middle">C</text><rect class="dl" x="450" y="304" width="26" height="20" rx="2" /><text class="xs h" x="463" y="318" text-anchor="middle">C</text><rect class="grp" x="480" y="304" width="66" height="20" rx="2" /><rect class="grp" x="585" y="174" width="165" height="172" rx="6" /><text class="s h" x="667" y="192" text-anchor="middle">Reclaim group RG1</text><rect class="box" x="597" y="214" width="141" height="54" rx="6" /><text class="xs d" x="667" y="246" text-anchor="middle">reclaim unit</text><rect class="box" x="597" y="280" width="141" height="54" rx="6" /><text class="xs d" x="667" y="312" text-anchor="middle">reclaim unit</text><rect class="pl" x="10" y="358" width="560" height="66" rx="6" /><text class="xs" x="24" y="378" text-anchor="start">Each lifetime class fills its own RU, so a whole RU tends to die together.</text><text class="xs" x="24" y="394" text-anchor="start">Reclaim then finds a mostly invalid RU and cold data is not dragged along.</text><text class="xs d" x="24" y="410" text-anchor="start">Reclaim is still the controller job: the host cannot erase or reset an RU.</text><rect class="box" x="585" y="358" width="165" height="66" rx="6" /><text class="xs" x="667" y="380" text-anchor="middle">PID 8003h = handle 3</text><text class="xs d" x="667" y="394" text-anchor="middle">in RG1 (2 RGs, RGIF = 1:</text><text class="xs d" x="667" y="408" text-anchor="middle">RG in the top bit)</text></svg>`};
DIAGRAMS.ftl={title:'FTL: write somewhere else, invalidate the old copy',cap:'A write programs a new page and repoints the L2P entry, which turns the old page invalid without erasing anything. Green pages are valid, red is invalid, amber is the newest copy and dashed cells are free. GC reclaims blocks later.',svg:`<svg viewBox="0 0 760 406" role="img" aria-label="Logical to physical mapping, out-of-place write, and the garbage collection flow"><title>Logical to physical mapping, out-of-place write, and the garbage collection flow</title><rect class="tl" x="10" y="20" width="180" height="46" rx="6" /><text class="h" x="100" y="40" text-anchor="middle">Host</text><text class="xs" x="100" y="56" text-anchor="middle">write LBA 100</text><line class="lna" x1="100" y1="66" x2="100.0" y2="102.0"/><polygon class="ah" points="100.0,110.0 95.5,101.0 104.5,101.0"/><rect class="dl" x="10" y="110" width="180" height="160" rx="6" /><text class="s h" x="100" y="130" text-anchor="middle">FTL: L2P table</text><text class="xs d" x="100" y="144" text-anchor="middle">held in DRAM</text><rect class="tl" x="38" y="156" width="140" height="30" rx="6" /><text class="s h" x="108" y="176" text-anchor="middle">L2P[100] = P1</text><text class="xs d" x="100" y="204" text-anchor="middle">before the write: P0</text><text class="xs d" x="100" y="236" text-anchor="middle">a read looks up this</text><text class="xs d" x="100" y="250" text-anchor="middle">entry first</text><rect class="box" x="240" y="34" width="250" height="90" rx="6" /><text class="xs h" x="365" y="52" text-anchor="middle">Block X (older data)</text><rect class="pl" x="252" y="62" width="25" height="28" rx="3" /><rect class="pl" x="281" y="62" width="25" height="28" rx="3" /><rect class="er" x="310" y="62" width="25" height="28" rx="3" /><text class="xs h" x="322.5" y="80" text-anchor="middle">P0</text><rect class="pl" x="339" y="62" width="25" height="28" rx="3" /><rect class="pl" x="368" y="62" width="25" height="28" rx="3" /><rect class="pl" x="397" y="62" width="25" height="28" rx="3" /><rect class="pl" x="426" y="62" width="25" height="28" rx="3" /><rect class="pl" x="455" y="62" width="25" height="28" rx="3" /><text class="xs rd" x="365" y="112" text-anchor="middle">P0: invalid, still in NAND</text><rect class="box" x="240" y="170" width="250" height="90" rx="6" /><text class="xs h" x="365" y="188" text-anchor="middle">Open block Y</text><rect class="pl" x="252" y="198" width="25" height="28" rx="3" /><rect class="pl" x="281" y="198" width="25" height="28" rx="3" /><rect class="pl" x="310" y="198" width="25" height="28" rx="3" /><rect class="tl" x="339" y="198" width="25" height="28" rx="3" /><text class="xs h" x="351.5" y="216" text-anchor="middle">P1</text><rect class="grp" x="368" y="198" width="25" height="28" rx="3" /><rect class="grp" x="397" y="198" width="25" height="28" rx="3" /><rect class="grp" x="426" y="198" width="25" height="28" rx="3" /><rect class="grp" x="455" y="198" width="25" height="28" rx="3" /><text class="xs ac" x="365" y="248" text-anchor="middle">P1: newest copy, valid</text><line class="lna" x1="190" y1="212" x2="232.0" y2="212.0"/><polygon class="ah" points="240.0,212.0 231.0,216.5 231.0,207.5"/><polyline class="lnr" points="190,140 215,140 215,79 232.0,79.0"/><polygon class="ahr" points="240.0,79.0 231.0,83.5 231.0,74.5"/><rect class="tl" x="207" y="102" width="16" height="16" rx="8" /><text class="xs h" x="215" y="113.5" text-anchor="middle">3</text><rect class="tl" x="207" y="182" width="16" height="16" rx="8" /><text class="xs h" x="215" y="193.5" text-anchor="middle">1</text><rect class="tl" x="16" y="163" width="16" height="16" rx="8" /><text class="xs h" x="24" y="174.5" text-anchor="middle">2</text><text class="s h" x="520" y="24" text-anchor="start">Later: garbage collection</text><rect class="pl" x="520" y="34" width="230" height="46" rx="6" /><text class="s h" x="635" y="54" text-anchor="middle">Pick a victim block</text><text class="xs d" x="635" y="70" text-anchor="middle">most of its pages invalid</text><line class="lna" x1="635" y1="80" x2="635.0" y2="88.0"/><polygon class="ah" points="635.0,96.0 630.5,87.0 639.5,87.0"/><rect class="pl" x="520" y="96" width="230" height="46" rx="6" /><text class="s h" x="635" y="116" text-anchor="middle">Copy the valid pages</text><text class="xs d" x="635" y="132" text-anchor="middle">valid = L2P still points here</text><line class="lna" x1="635" y1="142" x2="635.0" y2="150.0"/><polygon class="ah" points="635.0,158.0 630.5,149.0 639.5,149.0"/><rect class="dl" x="520" y="158" width="230" height="46" rx="6" /><text class="s h" x="635" y="178" text-anchor="middle">Update L2P</text><text class="xs d" x="635" y="194" text-anchor="middle">for each page that moved</text><line class="lna" x1="635" y1="204" x2="635.0" y2="212.0"/><polygon class="ah" points="635.0,220.0 630.5,211.0 639.5,211.0"/><rect class="pl" x="520" y="220" width="230" height="46" rx="6" /><text class="s h" x="635" y="240" text-anchor="middle">Erase the victim</text><text class="xs d" x="635" y="256" text-anchor="middle">block joins the free pool</text><rect class="tl" x="16" y="235" width="16" height="16" rx="8" /><text class="xs h" x="24" y="246.5" text-anchor="middle">4</text><rect class="box" x="10" y="290" width="740" height="104" rx="6" /><text class="s h ac" x="24" y="310" text-anchor="start">1</text><text class="xs" x="42" y="310" text-anchor="start">The FTL takes the next free page P1 in the open block and programs the new data there.</text><text class="s h ac" x="24" y="328" text-anchor="start">2</text><text class="xs" x="42" y="328" text-anchor="start">L2P[100] changes from P0 to P1.</text><text class="s h ac" x="24" y="346" text-anchor="start">3</text><text class="xs" x="42" y="346" text-anchor="start">The old copy P0 is marked invalid. Nothing is erased; P0 stays in NAND.</text><text class="s h ac" x="24" y="364" text-anchor="start">4</text><text class="xs" x="42" y="364" text-anchor="start">A read of LBA 100 uses L2P[100] to find P1. An unmapped entry needs no NAND read.</text><text class="xs" x="42" y="382" text-anchor="start">Each page also stores its LBA, so GC can compare it with the L2P entry.</text></svg>`};
DIAGRAMS.gc={title:'Write amplification from the GC victim valid fraction',cap:'One 8-page victim block with 6 valid pages: GC copies 6, the erase nets 2 free pages, 2 host pages fill them, so 8 NAND writes serve 2 host writes and WAF = 8 / 2 = 4. The bars show WAF = 1/(1-u); the u = 0.75 case is highlighted.',svg:`<svg viewBox="0 0 760 306" role="img" aria-label="Worked write amplification example with valid and invalid pages in a GC victim block"><title>Worked write amplification example with valid and invalid pages in a GC victim block</title><text class="s h" x="97" y="20" text-anchor="middle">Victim block</text><text class="xs d" x="97" y="34" text-anchor="middle">N = 8: 6 valid, 2 invalid</text><text class="s h" x="362" y="20" text-anchor="middle">New block (GC target)</text><text class="xs d" x="362" y="34" text-anchor="middle">takes the 6 valid pages</text><text class="s h" x="627" y="20" text-anchor="middle">Same block, filled</text><text class="xs d" x="627" y="34" text-anchor="middle">2 host pages arrive</text><rect class="pl" x="10" y="44" width="20" height="24" rx="2" /><rect class="pl" x="32" y="44" width="20" height="24" rx="2" /><rect class="er" x="54" y="44" width="20" height="24" rx="2" /><rect class="pl" x="76" y="44" width="20" height="24" rx="2" /><rect class="pl" x="98" y="44" width="20" height="24" rx="2" /><rect class="pl" x="120" y="44" width="20" height="24" rx="2" /><rect class="er" x="142" y="44" width="20" height="24" rx="2" /><rect class="pl" x="164" y="44" width="20" height="24" rx="2" /><rect class="dl" x="275" y="44" width="20" height="24" rx="2" /><rect class="dl" x="297" y="44" width="20" height="24" rx="2" /><rect class="dl" x="319" y="44" width="20" height="24" rx="2" /><rect class="dl" x="341" y="44" width="20" height="24" rx="2" /><rect class="dl" x="363" y="44" width="20" height="24" rx="2" /><rect class="dl" x="385" y="44" width="20" height="24" rx="2" /><rect class="grp" x="407" y="44" width="20" height="24" rx="2" /><rect class="grp" x="429" y="44" width="20" height="24" rx="2" /><rect class="dl" x="540" y="44" width="20" height="24" rx="2" /><rect class="dl" x="562" y="44" width="20" height="24" rx="2" /><rect class="dl" x="584" y="44" width="20" height="24" rx="2" /><rect class="dl" x="606" y="44" width="20" height="24" rx="2" /><rect class="dl" x="628" y="44" width="20" height="24" rx="2" /><rect class="dl" x="650" y="44" width="20" height="24" rx="2" /><rect class="tl" x="672" y="44" width="20" height="24" rx="2" /><rect class="tl" x="694" y="44" width="20" height="24" rx="2" /><text class="s ac" x="97" y="86" text-anchor="middle">u = 6 / 8 = 0.75</text><text class="xs gr" x="97" y="100" text-anchor="middle">then erased: block is free</text><text class="xs" x="362" y="86" text-anchor="middle">6 NAND writes, no host data</text><text class="xs" x="627" y="86" text-anchor="middle">room gained 8 - 6 = 2 pages</text><line class="lna" x1="184" y1="56" x2="267.0" y2="56.0"/><polygon class="ah" points="275.0,56.0 266.0,60.5 266.0,51.5"/><text class="xs" x="229" y="48" text-anchor="middle">copy 6 valid</text><line class="lna" x1="449" y1="56" x2="532.0" y2="56.0"/><polygon class="ah" points="540.0,56.0 531.0,60.5 531.0,51.5"/><text class="xs" x="494" y="48" text-anchor="middle">host: 2 pages</text><rect class="pl" x="10" y="114" width="12" height="12" rx="2" /><text class="xs" x="28" y="124" text-anchor="start">valid</text><rect class="er" x="90" y="114" width="12" height="12" rx="2" /><text class="xs" x="108" y="124" text-anchor="start">invalid</text><rect class="dl" x="180" y="114" width="12" height="12" rx="2" /><text class="xs" x="198" y="124" text-anchor="start">GC copy</text><rect class="tl" x="280" y="114" width="12" height="12" rx="2" /><text class="xs" x="298" y="124" text-anchor="start">host write</text><rect class="grp" x="400" y="114" width="12" height="12" rx="2" /><text class="xs" x="418" y="124" text-anchor="start">free</text><rect class="box" x="10" y="144" width="360" height="152" rx="6" /><text class="s h" x="190" y="164" text-anchor="middle">Count the NAND writes</text><text class="xs" x="26" y="188" text-anchor="start">GC copies of valid pages</text><text class="s h" x="354" y="188" text-anchor="end">6</text><text class="xs" x="26" y="206" text-anchor="start">host pages written</text><text class="s h" x="354" y="206" text-anchor="end">2</text><line class="ln" x1="26" y1="214" x2="354" y2="214"/><text class="xs" x="26" y="230" text-anchor="start">NAND writes = 6 + 2</text><text class="s h" x="354" y="230" text-anchor="end">8</text><text class="xs" x="26" y="248" text-anchor="start">host writes</text><text class="s h" x="354" y="248" text-anchor="end">2</text><text class="s h ac" x="190" y="276" text-anchor="middle">WAF = 8 / 2 = 4 = 1 / (1 - 0.75)</text><text class="s h" x="400" y="164" text-anchor="start">WAF = 1 / (1 - u)</text><text class="xs d" x="750" y="164" text-anchor="end">u = victim valid fraction</text><text class="xs" x="400" y="193" text-anchor="start">u = 0.00</text><rect class="dl" x="466" y="178" width="24.0" height="20" rx="2" /><text class="s" x="498.0" y="193" text-anchor="start">1.0</text><text class="xs" x="400" y="221" text-anchor="start">u = 0.50</text><rect class="dl" x="466" y="206" width="48.0" height="20" rx="2" /><text class="s" x="522.0" y="221" text-anchor="start">2.0</text><text class="xs h" x="400" y="249" text-anchor="start">u = 0.75</text><rect class="tl" x="466" y="234" width="96.0" height="20" rx="2" /><text class="s h" x="570.0" y="249" text-anchor="start">4.0</text><text class="xs" x="400" y="277" text-anchor="start">u = 0.90</text><rect class="dl" x="466" y="262" width="240.00000000000006" height="20" rx="2" /><text class="s" x="714.0" y="277" text-anchor="start">10.0</text></svg>`};
DIAGRAMS.latstack={title:'Latency budget for a 4 KiB random read',cap:'Segment widths are to scale. Amber is host software, the dark unfilled segment is PCIe, blue is controller firmware and hardware, green is NAND. At QD1 the media dominates, and the tail comes from events that add whole NAND operations, such as retries or a wait behind a program or erase.',svg:`<svg viewBox="0 0 760 408" role="img" aria-label="Latency budget stack for a 4 KiB random read across host, PCIe, controller and NAND"><title>Latency budget stack for a 4 KiB random read across host, PCIe, controller and NAND</title><text class="s h" x="20" y="20" text-anchor="start">One 4 KiB random read at QD1: about 82 us (illustrative TLC drive, Gen4 x4)</text><rect class="tl" x="20.0" y="56" width="52.7" height="40" rx="2" /><rect class="box" x="72.7" y="56" width="26.3" height="40" rx="2" /><rect class="dl" x="99.0" y="56" width="61.5" height="40" rx="2" /><rect class="pl" x="160.5" y="56" width="579.5" height="40" rx="2" /><text class="s h" x="46.34146341463415" y="74" text-anchor="middle">Host</text><text class="xs" x="46.34146341463415" y="88" text-anchor="middle">6 us</text><text class="xs" x="85.85365853658537" y="48" text-anchor="middle">PCIe 3 us</text><text class="s h" x="129.7560975609756" y="74" text-anchor="middle">FW</text><text class="xs" x="129.7560975609756" y="88" text-anchor="middle">7 us</text><text class="s h" x="450.2439024390244" y="74" text-anchor="middle">NAND 66 us</text><text class="xs d" x="450.2439024390244" y="88" text-anchor="middle">about 80 percent of the total</text><line class="lnd" x1="160.5" y1="96" x2="20" y2="160"/><line class="lnd" x1="740" y1="96" x2="740" y2="160"/><rect class="pl" x="20" y="160" width="653.6" height="36" rx="2" /><text class="s h" x="346.7776096822996" y="182" text-anchor="middle">tR about 60 us (array read)</text><rect class="pl" x="673.6" y="160" width="39.2" height="36" rx="2" /><rect class="pl" x="712.8" y="160" width="27.2" height="36" rx="2" /><line class="ln" x1="693.2" y1="196" x2="693.2" y2="214"/><text class="xs" x="699.2" y="226" text-anchor="end">channel transfer 3.6 us</text><line class="ln" x1="726.4" y1="196" x2="726.4" y2="244"/><text class="xs" x="732.4" y="256" text-anchor="end">ECC decode 2.5 us</text><text class="xs d" x="20" y="226" text-anchor="start">NAND zoomed to full width:</text><text class="xs d" x="20" y="240" text-anchor="start">tR + transfer + ECC = about 66 us</text><text class="s h" x="20" y="288" text-anchor="start">Where the tail comes from, by layer</text><rect class="tl" x="20" y="298" width="171" height="98" rx="6" /><text class="s h" x="105" y="316" text-anchor="middle">Host software  6 us</text><text class="xs d" x="105" y="334" text-anchor="middle">interrupt moderation</text><text class="xs d" x="105" y="348" text-anchor="middle">CPU C-states</text><text class="xs d" x="105" y="362" text-anchor="middle">softirq scheduling</text><rect class="box" x="203" y="298" width="171" height="98" rx="6" /><text class="s h" x="288" y="316" text-anchor="middle">PCIe  3 us</text><text class="xs d" x="288" y="334" text-anchor="middle">replay or retrain</text><text class="xs d" x="288" y="348" text-anchor="middle">adds microseconds</text><text class="xs d" x="288" y="362" text-anchor="middle">to milliseconds</text><rect class="dl" x="386" y="298" width="171" height="98" rx="6" /><text class="s h" x="471" y="316" text-anchor="middle">Controller FW  7 us</text><text class="xs d" x="471" y="334" text-anchor="middle">housekeeping, GC work</text><text class="xs d" x="471" y="348" text-anchor="middle">journal or checkpoint</text><text class="xs d" x="471" y="362" text-anchor="middle">error handling</text><rect class="pl" x="569" y="298" width="171" height="98" rx="6" /><text class="s h" x="654" y="316" text-anchor="middle">NAND  66 us</text><text class="xs d" x="654" y="334" text-anchor="middle">read retry: about 60 us</text><text class="xs d" x="654" y="348" text-anchor="middle">more per attempt</text><text class="xs d" x="654" y="362" text-anchor="middle">read stuck behind a</text><text class="xs d" x="654" y="376" text-anchor="middle">program or erase</text></svg>`};
DIAGRAMS.swstack={title:'Linux NVMe host stack and tool tap points',cap:'Each tool sees only what crosses the layer where it attaches. Amber layers are the kernel host path, blue is the SSD, and dots mark where each tool taps in. The dashed path is SPDK, which bypasses the kernel nvme driver through VFIO.',svg:`<svg viewBox="0 0 760 436" role="img" aria-label="Linux NVMe host stack layers with the tools that tap into each layer"><title>Linux NVMe host stack layers with the tools that tap into each layer</title><rect class="grp" x="140" y="22" width="284" height="346" rx="8" /><text class="xs d" x="146" y="15" text-anchor="start">Linux host stack</text><rect class="tl" x="150" y="40" width="260" height="44" rx="6" /><text class="s h" x="280.0" y="66.0" text-anchor="middle">Applications and filesystems</text><rect class="tl" x="150" y="100" width="260" height="44" rx="6" /><text class="s h" x="280.0" y="119.0" text-anchor="middle">Block layer with blk-mq</text><text class="xs d" x="280.0" y="133.0" text-anchor="middle">requests, one hctx per NVMe queue</text><rect class="tl" x="150" y="160" width="260" height="76" rx="6" /><text class="s h" x="280.0" y="195.0" text-anchor="middle">nvme-core (nvme_core.ko)</text><text class="xs d" x="280.0" y="209.0" text-anchor="middle">state machine, Identify, ioctls</text><rect class="tl" x="150" y="252" width="260" height="44" rx="6" /><text class="s h" x="280.0" y="271.0" text-anchor="middle">nvme PCIe transport (nvme.ko)</text><text class="xs d" x="280.0" y="285.0" text-anchor="middle">BAR0, queues, doorbells, MSI-X</text><rect class="tl" x="150" y="312" width="260" height="44" rx="6" /><text class="s h" x="280.0" y="331.0" text-anchor="middle">PCI core</text><text class="xs d" x="280.0" y="345.0" text-anchor="middle">enumeration, hot-plug, AER, resets</text><line class="ln" x1="280.0" y1="84" x2="280.0" y2="100"/><line class="ln" x1="280.0" y1="144" x2="280.0" y2="160"/><line class="ln" x1="280.0" y1="236" x2="280.0" y2="252"/><line class="ln" x1="280.0" y1="296" x2="280.0" y2="312"/><rect class="dl" x="10" y="386" width="400" height="40" rx="6" /><text class="h" x="210.0" y="411" text-anchor="middle">NVMe SSD</text><line class="ln" x1="280.0" y1="356" x2="280.0" y2="386"/><rect class="box" x="10" y="40" width="108" height="56" rx="6" /><text class="s h" x="64" y="58" text-anchor="middle">SPDK</text><text class="xs d" x="64" y="73" text-anchor="middle">user-space</text><text class="xs d" x="64" y="87" text-anchor="middle">driver</text><line class="lnd" x1="30" y1="96" x2="30.0" y2="378.0"/><polygon class="ahd" points="30.0,386.0 25.5,377.0 34.5,377.0"/><text class="xs d" x="42" y="190" text-anchor="start">via VFIO,</text><text class="xs d" x="42" y="203" text-anchor="start">bypasses the</text><text class="xs d" x="42" y="216" text-anchor="start">kernel nvme</text><text class="xs d" x="42" y="229" text-anchor="start">path</text><rect class="box" x="456" y="40" width="296" height="38" rx="6" /><text class="s h" x="604.0" y="56" text-anchor="middle">fio, filesystem tests</text><text class="xs d" x="604.0" y="70" text-anchor="middle">top: block device or file, end to end</text><rect class="box" x="456" y="86" width="296" height="38" rx="6" /><text class="s h" x="604.0" y="102" text-anchor="middle">blktrace, block tracepoints</text><text class="xs d" x="604.0" y="116" text-anchor="middle">block layer, above the driver</text><rect class="box" x="456" y="132" width="296" height="38" rx="6" /><text class="s h" x="604.0" y="148" text-anchor="middle">nvme-cli, passthrough</text><text class="xs d" x="604.0" y="162" text-anchor="middle">ioctl on /dev/nvmeX char devices</text><rect class="box" x="456" y="178" width="296" height="38" rx="6" /><text class="s h" x="604.0" y="194" text-anchor="middle">sysfs, /proc/interrupts</text><text class="xs d" x="604.0" y="208" text-anchor="middle">controller, queue and IRQ mapping state</text><rect class="box" x="456" y="224" width="296" height="38" rx="6" /><text class="s h" x="604.0" y="240" text-anchor="middle">ftrace nvme events</text><text class="xs d" x="604.0" y="254" text-anchor="middle">inside nvme-core: setup and completion</text><rect class="box" x="456" y="270" width="296" height="38" rx="6" /><text class="s h" x="604.0" y="286" text-anchor="middle">dmesg, journalctl -k</text><text class="xs d" x="604.0" y="300" text-anchor="middle">printk from nvme-core, nvme, PCI core</text><rect class="box" x="456" y="316" width="296" height="38" rx="6" /><text class="s h" x="604.0" y="332" text-anchor="middle">perf, bpftrace</text><text class="xs d" x="604.0" y="346" text-anchor="middle">kprobes and tracepoints at any layer</text><line class="ln" x1="456" y1="59.0" x2="410" y2="62"/><circle class="ah" cx="410" cy="62" r="3.5"/><line class="ln" x1="456" y1="105.0" x2="410" y2="122"/><circle class="ah" cx="410" cy="122" r="3.5"/><line class="ln" x1="456" y1="151.0" x2="410" y2="172"/><circle class="ah" cx="410" cy="172" r="3.5"/><line class="ln" x1="456" y1="197.0" x2="410" y2="192"/><circle class="ah" cx="410" cy="192" r="3.5"/><line class="ln" x1="456" y1="243.0" x2="396" y2="210"/><circle class="ah" cx="396" cy="210" r="3.5"/><line class="ln" x1="456" y1="289.0" x2="410" y2="224"/><circle class="ah" cx="410" cy="224" r="3.5"/><line class="ln" x1="456" y1="289.0" x2="410" y2="276"/><circle class="ah" cx="410" cy="276" r="3.5"/><line class="ln" x1="456" y1="289.0" x2="410" y2="336"/><circle class="ah" cx="410" cy="336" r="3.5"/><line class="ln" x1="456" y1="335.0" x2="422" y2="352"/><circle class="ah" cx="422" cy="352" r="3.5"/></svg>`};
DIAGRAMS.valpyramid={title:'The validation pyramid',cap:'Many fast tests sit at the base, few slow ones at the top. Amber layers run before real silicon exists, blue layers run on real hardware. Each layer catches a class of bug the others cannot, and finds it cheaper than the next one up.',svg:`<svg viewBox="0 0 760 412" role="img" aria-label="Validation pyramid from unit test at the base to system test at the top, with what each layer catches and misses"><title>Validation pyramid from unit test at the base to system test at the top, with what each layer catches and misses</title><text class="xs d" x="196" y="16" text-anchor="middle">layer, what it runs, turn time</text><text class="xs d" x="400" y="16" text-anchor="start">what it catches, and what it is blind to</text><polygon class="dl" points="108.0,34 284.0,34 302.6,96 89.4,96"/><text class="s h" x="196" y="55" text-anchor="middle">System and platform</text><text class="xs d" x="196" y="71" text-anchor="middle">real hosts, OSes, workloads</text><text class="xs ac" x="196" y="86" text-anchor="middle">turn: days to weeks</text><text class="xs h gr" x="400" y="54" text-anchor="start">catches</text><text class="xs" x="458" y="54" text-anchor="start">interop with real BIOS, OS, drivers, RAID and HBAs,</text><text class="xs" x="458" y="67" text-anchor="start">long soak, compliance</text><text class="xs h rd" x="400" y="86" text-anchor="start">blind to</text><text class="xs d" x="458" y="86" text-anchor="start">root cause: shows the symptom, not the layer</text><polygon class="dl" points="88.2,100 303.8,100 322.5,162 69.5,162"/><text class="s h" x="196" y="121" text-anchor="middle">Silicon characterization</text><text class="xs d" x="196" y="137" text-anchor="middle">timing, NAND and PHY behavior</text><text class="xs ac" x="196" y="152" text-anchor="middle">turn: days</text><text class="xs h gr" x="400" y="120" text-anchor="start">catches</text><text class="xs" x="458" y="120" text-anchor="start">PHY and link margin, NAND timing and error rates,</text><text class="xs" x="458" y="133" text-anchor="start">power, thermal, ECC margin</text><text class="xs h rd" x="400" y="152" text-anchor="start">blind to</text><text class="xs d" x="458" y="152" text-anchor="start">rare host behaviors you have not plugged in</text><polygon class="tl" points="68.3,166 323.7,166 342.3,228 49.7,228"/><text class="s h" x="196" y="187" text-anchor="middle">Emulation or FPGA with RTL</text><text class="xs d" x="196" y="203" text-anchor="middle">firmware on real RTL</text><text class="xs ac" x="196" y="218" text-anchor="middle">turn: hours, MHz-class speed</text><text class="xs h gr" x="400" y="186" text-anchor="start">catches</text><text class="xs" x="458" y="186" text-anchor="start">HW/FW interface bugs, DMA and doorbell races,</text><text class="xs" x="458" y="199" text-anchor="start">register semantics, PCIe MAC behavior</text><text class="xs h rd" x="400" y="218" text-anchor="start">blind to</text><text class="xs d" x="458" y="218" text-anchor="start">real NAND, real PHY, full-speed performance</text><polygon class="tl" points="48.5,232 343.5,232 362.2,294 29.8,294"/><text class="s h" x="196" y="253" text-anchor="middle">FW simulation</text><text class="xs d" x="196" y="269" text-anchor="middle">virtual controller and NAND model</text><text class="xs ac" x="196" y="284" text-anchor="middle">turn: minutes</text><text class="xs h gr" x="400" y="252" text-anchor="start">catches</text><text class="xs" x="458" y="252" text-anchor="start">command flow, FTL and GC logic, exhaustive power-cut</text><text class="xs" x="458" y="265" text-anchor="start">points, error injection, deterministic replay</text><text class="xs h rd" x="400" y="284" text-anchor="start">blind to</text><text class="xs d" x="458" y="284" text-anchor="start">real latencies, HW quirks, NAND analog behavior</text><polygon class="tl" points="28.6,298 363.4,298 382.0,360 10.0,360"/><text class="s h" x="196" y="319" text-anchor="middle">Unit</text><text class="xs d" x="196" y="335" text-anchor="middle">host-compiled firmware, mocked HW</text><text class="xs ac" x="196" y="350" text-anchor="middle">turn: seconds, every commit</text><text class="xs h gr" x="400" y="318" text-anchor="start">catches</text><text class="xs" x="458" y="318" text-anchor="start">logic and boundary bugs in parsers, FTL algorithms,</text><text class="xs" x="458" y="331" text-anchor="start">ECC math, state machines</text><text class="xs h rd" x="400" y="350" text-anchor="start">blind to</text><text class="xs d" x="458" y="350" text-anchor="start">timing, real HW registers, multi-core concurrency</text><text class="s d" x="20" y="382" text-anchor="start">Test count and speed grow toward the base. Cost per bug and turn time grow toward the top.</text><text class="s d" x="20" y="400" text-anchor="start">Rule: push every bug to the lowest layer that can reproduce it.</text></svg>`};
DIAGRAMS.triage={title:'Fault-isolation decision tree',cap:'Ask in order and stop at the first question that answers. Steps 1 to 3 are cheap reads on the failing system, and the analyzer comes last. Leaf color is the first bucket named: amber host, red link, blue controller, green media.',svg:`<svg viewBox="0 0 760 436" role="img" aria-label="Decision tree that sends a failing SSD to the host, link, controller or media bucket"><title>Decision tree that sends a failing SSD to the host, link, controller or media bucket</title><rect class="box" x="8" y="5.0" width="192" height="32" rx="6" /><text class="s h" x="104.0" y="18.5" text-anchor="middle">Step 1: function present?</text><text class="xs d" x="104.0" y="31.5" text-anchor="middle">config space Vendor ID, LnkSta</text><rect class="box" x="8" y="59.0" width="192" height="32" rx="6" /><text class="s h" x="104.0" y="72.5" text-anchor="middle">Step 2: controller alive?</text><text class="xs d" x="104.0" y="85.5" text-anchor="middle">CSTS and CC, after step 1</text><rect class="box" x="8" y="112" width="192" height="114" rx="6" /><text class="s h" x="104.0" y="166.5" text-anchor="middle">Step 3: commands complete?</text><text class="xs d" x="104.0" y="179.5" text-anchor="middle">and with which status type?</text><rect class="box" x="234" y="246" width="180" height="34" rx="6" /><text class="s h" x="324.0" y="260.5" text-anchor="middle">Step 4: timeout</text><text class="xs d" x="324.0" y="273.5" text-anchor="middle">CQE already in host memory?</text><rect class="box" x="234" y="300" width="180" height="72" rx="6" /><text class="s h" x="324.0" y="327.0" text-anchor="middle">Step 4: no CQE yet</text><text class="xs d" x="324.0" y="340.0" text-anchor="middle">was the SQE fetched?</text><text class="xs d" x="324.0" y="353.0" text-anchor="middle">analyzer or SSD log</text><rect class="box" x="234" y="392" width="180" height="34" rx="6" /><text class="s h" x="324.0" y="406.5" text-anchor="middle">Step 5: Success returned</text><text class="xs d" x="324.0" y="419.5" text-anchor="middle">is the data right?</text><line class="ln" x1="68" y1="37.0" x2="68.0" y2="51.0"/><polygon class="ahd" points="68.0,59.0 63.5,50.0 72.5,50.0"/><text class="xs d" x="76" y="51.0" text-anchor="start">valid ID</text><line class="ln" x1="68" y1="91.0" x2="68.0" y2="104.0"/><polygon class="ahd" points="68.0,112.0 63.5,103.0 72.5,103.0"/><text class="xs d" x="76" y="105.0" text-anchor="start">CFS clear, RDY held</text><rect class="er" x="548" y="5.0" width="204" height="32" rx="6" /><text class="s h" x="650.0" y="19" text-anchor="middle">Link</text><text class="xs d" x="650.0" y="31" text-anchor="middle">slot power, or device gone</text><line class="lnr" x1="200" y1="21" x2="540.0" y2="21.0"/><polygon class="ahr" points="548.0,21.0 539.0,25.5 539.0,16.5"/><text class="xs d" x="374.0" y="15" text-anchor="middle">No: config read returns all ones</text><rect class="dl" x="548" y="59.0" width="204" height="32" rx="6" /><text class="s h" x="650.0" y="79" text-anchor="middle">Controller firmware</text><line class="lnc" x1="200" y1="75" x2="540.0" y2="75.0"/><polygon class="ahc" points="548.0,75.0 539.0,79.5 539.0,70.5"/><text class="xs d" x="374.0" y="69" text-anchor="middle">CFS = 1, or RDY fell unexpectedly</text><rect class="pl" x="548" y="113.0" width="204" height="32" rx="6" /><text class="s h" x="650.0" y="133" text-anchor="middle">Media or FTL</text><line class="lng" x1="200" y1="129" x2="540.0" y2="129.0"/><polygon class="ah" points="548.0,129.0 539.0,133.5 539.0,124.5"/><text class="xs d" x="374.0" y="123" text-anchor="middle">SCT 2: media and data integrity failure</text><rect class="er" x="548" y="153.0" width="204" height="32" rx="6" /><text class="s h" x="650.0" y="173" text-anchor="middle">Link or host memory path</text><line class="lnr" x1="200" y1="169" x2="540.0" y2="169.0"/><polygon class="ahr" points="548.0,169.0 539.0,173.5 539.0,164.5"/><text class="xs d" x="374.0" y="163" text-anchor="middle">status 04h Data Transfer Error: a DMA failed</text><rect class="tl" x="548" y="193.0" width="204" height="32" rx="6" /><text class="s h" x="650.0" y="207" text-anchor="middle">Host</text><text class="xs d" x="650.0" y="219" text-anchor="middle">unless legal command rejected</text><line class="lna" x1="200" y1="209" x2="540.0" y2="209.0"/><polygon class="ah" points="548.0,209.0 539.0,213.5 539.0,204.5"/><text class="xs d" x="374.0" y="203" text-anchor="middle">status 01h, 02h, 0Bh: the command was wrong</text><rect class="tl" x="548" y="247.0" width="204" height="32" rx="6" /><text class="s h" x="650.0" y="261" text-anchor="middle">Host interrupt path</text><text class="xs d" x="650.0" y="273" text-anchor="middle">or firmware signaling</text><line class="lna" x1="414" y1="263" x2="540.0" y2="263.0"/><polygon class="ah" points="548.0,263.0 539.0,267.5 539.0,258.5"/><text class="xs d" x="481.0" y="257" text-anchor="middle">yes: CQE is there</text><rect class="er" x="548" y="300.0" width="204" height="32" rx="6" /><text class="s h" x="650.0" y="314" text-anchor="middle">Link, host BAR access</text><text class="xs d" x="650.0" y="326" text-anchor="middle">or firmware</text><line class="lnr" x1="414" y1="316" x2="540.0" y2="316.0"/><polygon class="ahr" points="548.0,316.0 539.0,320.5 539.0,311.5"/><text class="xs d" x="481.0" y="310" text-anchor="middle">no: no SQE fetch</text><rect class="dl" x="548" y="340.0" width="204" height="32" rx="6" /><text class="s h" x="650.0" y="360" text-anchor="middle">Firmware or NAND stall</text><line class="lnc" x1="414" y1="356" x2="540.0" y2="356.0"/><polygon class="ahc" points="548.0,356.0 539.0,360.5 539.0,351.5"/><text class="xs d" x="481.0" y="350" text-anchor="middle">yes: fetched, no CQE</text><rect class="pl" x="548" y="393.0" width="204" height="32" rx="6" /><text class="s h" x="650.0" y="407" text-anchor="middle">Media or FTL</text><text class="xs d" x="650.0" y="419" text-anchor="middle">or transport and host buffer</text><line class="lng" x1="414" y1="409" x2="540.0" y2="409.0"/><polygon class="ah" points="548.0,409.0 539.0,413.5 539.0,404.5"/><text class="xs d" x="481.0" y="403" text-anchor="middle">no: data is wrong</text><polyline class="ln" points="150,226 150,263 226.0,263.0"/><polygon class="ahd" points="234.0,263.0 225.0,267.5 225.0,258.5"/><text class="xs d" x="192" y="257" text-anchor="middle">timeout</text><polyline class="ln" points="60,226 60,409 226.0,409.0"/><polygon class="ahd" points="234.0,409.0 225.0,413.5 225.0,404.5"/><text class="xs d" x="147" y="403" text-anchor="middle">Success</text><line class="ln" x1="324" y1="280" x2="324.0" y2="292.0"/><polygon class="ahd" points="324.0,300.0 319.5,291.0 328.5,291.0"/><text class="xs d" x="332" y="293" text-anchor="start">no CQE</text><text class="xs d" x="80" y="296" text-anchor="start">leaf color is the</text><text class="xs d" x="80" y="308" text-anchor="start">first bucket named</text><rect class="tl" x="80" y="318" width="16" height="11" rx="2" /><text class="xs" x="104" y="327" text-anchor="start">host</text><rect class="er" x="80" y="334" width="16" height="11" rx="2" /><text class="xs" x="104" y="343" text-anchor="start">link</text><rect class="dl" x="80" y="350" width="16" height="11" rx="2" /><text class="xs" x="104" y="359" text-anchor="start">controller</text><rect class="pl" x="80" y="366" width="16" height="11" rx="2" /><text class="xs" x="104" y="375" text-anchor="start">media</text></svg>`};
